(window.BUNKAZAI_DETAIL=window.BUNKAZAI_DETAIL||{})["c12"]=[{"id":"00013416","register_sub_id":"101","register_pk":"368501","name":"京都市美術館北案内板","kana":"きょうとしびじゅつかんきたあんないばん","category":"文化福祉","subcategory":"その他工作物","type_guess":"博物館","type_guess_confidence":"high","period":"昭和前","pref":"京都府","address":"京都府京都市左京区岡崎成勝寺町70","lat":35.01348889,"lng":135.78276667,"geo_status":"db","era":"昭和8年頃","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"鉄筋コンクリート造一部木造、銅板葺、間口3.3m","structure_material":"鉄筋コンクリート造一部木造","registered":"2020.08.17(令和2.08.17)","register_no":"26 － 0603","desc":"本館の正面である西面北寄りに建てた案内板。鉄筋コンクリート造で本館と同じタイル貼の柱を二本立て、木造の小屋組の上に切妻造銅板葺の屋根を載せる。柱間には木製の案内板を設置する。本館外観意匠との調和を図り、美術館の外構を構成する要素の一つ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013416"},{"id":"00013414","register_sub_id":"101","register_pk":"368499","name":"京都市美術館北門","kana":"きょうとしびじゅつかんきたもん","category":"文化福祉","subcategory":"その他工作物","type_guess":"博物館","type_guess_confidence":"high","period":"昭和前","pref":"京都府","address":"京都府京都市左京区岡崎成勝寺町50","lat":35.01359167,"lng":135.78391667,"geo_status":"db","era":"昭和8年頃","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"鉄筋コンクリート造、間口18m","structure_material":"鉄筋コンクリート造","registered":"2020.08.17(令和2.08.17)","register_no":"26 － 0601","desc":"敷地の北面に設けられた門で、間口一八メートルに配した二基の門柱からなる。鉄筋コンクリート造で、表面に花崗岩を貼る。四角柱の四隅を大きく面取りした八角形の断面で、高さは二メートルとする。北面の表構えを構成する要素の一つ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013414"},{"id":"00013412","register_sub_id":"101","register_pk":"368497","name":"京都市美術館正門（北）","kana":"きょうとしびじゅつかんせいもん（きた）","category":"文化福祉","subcategory":"その他工作物","type_guess":"博物館","type_guess_confidence":"high","period":"昭和前","pref":"京都府","address":"京都府京都市左京区岡崎成勝寺町70","lat":35.01315556,"lng":135.78274167,"geo_status":"db","era":"昭和8年頃","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"鉄筋コンクリート造、間口18m","structure_material":"鉄筋コンクリート造","registered":"2020.08.17(令和2.08.17)","register_no":"26 － 0599","desc":"本館の正面である西面に設けられた北側の正門で、間口一八メートルに配した二基の門柱からなる。鉄筋コンクリート造で、表面に花崗岩を貼る。四角柱の四隅を大きく面取りした八角形の断面で、高さは二メートルとする。美術館の表構えを構成する要素の一つ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013412"},{"id":"00013413","register_sub_id":"101","register_pk":"368498","name":"京都市美術館正門（南）","kana":"きょうとしびじゅつかんせいもん（みなみ）","category":"文化福祉","subcategory":"その他工作物","type_guess":"博物館","type_guess_confidence":"high","period":"昭和前","pref":"京都府","address":"京都府京都市左京区岡崎円勝寺町144","lat":35.0127,"lng":135.782775,"geo_status":"db","era":"昭和8年頃","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"鉄筋コンクリート造、間口18m","structure_material":"鉄筋コンクリート造","registered":"2020.08.17(令和2.08.17)","register_no":"26 － 0600","desc":"本館の正面である西面に設けられた南側の正門で、間口一八メートルに配した二基の門柱からなる。鉄筋コンクリート造で、表面に花崗岩を貼る。四角柱の四隅を大きく面取りした八角形の断面で、高さは二メートルとする。美術館の表構えを構成する要素の一つ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013413"},{"id":"00013415","register_sub_id":"101","register_pk":"368500","name":"京都市美術館東門","kana":"きょうとしびじゅつかんひがしもん","category":"文化福祉","subcategory":"その他工作物","type_guess":"博物館","type_guess_confidence":"high","period":"明治","pref":"京都府","address":"京都府京都市左京区岡崎成勝寺町50","lat":35.01289444,"lng":135.78465,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"石造、間口3.9m","structure_material":"石造","registered":"2020.08.17(令和2.08.17)","register_no":"26 － 0602","desc":"敷地の東面に設けられた門で、間口三・九メートルに配した二基の門柱からなる。花崗岩を用いた石造で、四隅を面取りし、側面に渦巻状の装飾を施す。イオニア式オーダーを想起させる意匠で、美術館の前身である京都商品陳列所の門として立てた。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013415"},{"id":"00013411","register_sub_id":"101","register_pk":"368496","name":"京都市美術館本館","kana":"きょうとしびじゅつかんほんかん","category":"文化福祉","subcategory":"建築物","type_guess":"博物館","type_guess_confidence":"high","period":"昭和前","pref":"京都府","address":"京都府京都市左京区岡崎円勝寺町124他","lat":35.01286111,"lng":135.78358333,"geo_status":"db","era":"昭和8年／令和元年改修","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"鉄筋コンクリート造一部鉄骨造地上2階地下1階建、銅板葺、建築面積4596㎡","structure_material":"鉄筋コンクリート造一部鉄骨造地上2階地下1階建","registered":"2020.08.17(令和2.08.17)","register_no":"26 － 0598","desc":"京都市左京区の南端に位置し、神宮道に西面して建つ。鉄筋コンクリート造一部鉄骨造、地上二階地下一階建で、四面中央に車寄付の入口を設ける。日本趣味を基調とするという条件で設計図案を公募し、和洋の様式を巧みに織り交ぜた意匠が評価された美術館。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013411"},{"id":"00013417","register_sub_id":"101","register_pk":"368502","name":"京都市美術館南案内板","kana":"きょうとしびじゅつかんみなみあんないばん","category":"文化福祉","subcategory":"その他工作物","type_guess":"博物館","type_guess_confidence":"high","period":"昭和前","pref":"京都府","address":"京都府京都市左京区岡崎円勝寺町144","lat":35.01225,"lng":135.78282222,"geo_status":"db","era":"昭和8年頃","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"鉄筋コンクリート造一部木造、銅板葺、間口3.3m","structure_material":"鉄筋コンクリート造一部木造","registered":"2020.08.17(令和2.08.17)","register_no":"26 － 0604","desc":"本館の正面である西面南寄りに建てた案内板。鉄筋コンクリート造で本館と同じタイル貼の柱を二本立て、木造の小屋組の上に切妻造銅板葺の屋根を載せる。柱間には木製の案内板を設置する。本館外観意匠との調和を図り、美術館の外構を構成する要素の一つ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013417"},{"id":"00000594","register_sub_id":"101","register_pk":"101584","name":"京都大学楽友会館","kana":"きょうとだいがくがくゆうかいかん","category":"文化福祉","subcategory":"建築物","type_guess":"会館","type_guess_confidence":"high","period":"大正","pref":"京都府","address":"京都府京都市左京区吉田近衛町","lat":35.0220308,"lng":135.77953243,"geo_status":"db","era":"大正14","year":1925,"year_source":"db","year_min":1925,"year_max":1925,"year_label":null,"structure":"鉄筋コンクリート造２階建，瓦葺，建築面積715㎡","structure_material":"鉄筋コンクリート造２階建","registered":"1998.07.23(平成10.07.23)","register_no":"26 － 0016","desc":"京大創立２５周年記念の同窓会館。分離派建築会の森田慶一が設計にあたる。スパニッシュ・ミッションを基調としながら，Ｙ字型の柱に支えられた円みをもつポーチ屋根が破調を与える。森谷延雄による家具とともに内部空間も大正建築の特徴をよく伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000594"},{"id":"00001198","register_sub_id":"101","register_pk":"102188","name":"京都大学基督教青年会会館","kana":"きょうとだいがくきりすときょうせいねんかいかいかん","category":"文化福祉","subcategory":"建築物","type_guess":"会館","type_guess_confidence":"high","period":"大正","pref":"京都府","address":"京都府京都市左京区吉田牛ノ宮町21、23","lat":35.02535138,"lng":135.77703403,"geo_status":"db","era":"大正2","year":1913,"year_source":"db","year_min":1913,"year_max":1913,"year_label":null,"structure":"煉瓦造２階建，スレート葺，建築面積197㎡","structure_material":"煉瓦造２階建","registered":"1999.07.08(平成11.07.08)","register_no":"26 － 0038","desc":"京都大学本部構内の西方、東一条通りに南面して建つ。モルタル塗でハーフティンバー風に見せている点に特徴がある。ヴォーリズの初期の作風の一端が窺われるとともに、大学ＹＭＣＡ会館の現存最古例としても貴重である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001198"},{"id":"00001923","register_sub_id":"101","register_pk":"102913","name":"京都大学人文科学研究所附属漢字情報研究センター","kana":"きょうとだいがくじんぶんかがくけんきゅうじょふぞくかんじじょうほうけんきゅうせんたー","category":"文化福祉","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"京都府","address":"京都府京都市左京区北白川東小倉町47","lat":35.03023658,"lng":135.78980921,"geo_status":"db","era":"昭和5","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"鉄筋コンクリート2階建、建築面積2436㎡、塔屋付","structure_material":"鉄筋コンクリート2階建","registered":"2000.10.18(平成12.10.18)","register_no":"26 － 0072","desc":"外務省東方文化学院京都研究所として建設。ＲＣ造，外壁スタッコ仕上で、塔付２階建の西棟と平屋建の他棟が中庭を囲みロ字形平面を構成する。スパニッシュ･ミッション様式を基調に外観･内装ともに高密度のデザインが施される。設計は武田五一と東畑謙三。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001923"},{"id":"00000739","register_sub_id":"101","register_pk":"101729","name":"京都大学文学部陳列館","kana":"きょうとだいがくぶんがくぶちんれつかん","category":"文化福祉","subcategory":"建築物","type_guess":"会館","type_guess_confidence":"low","period":"大正","pref":"京都府","address":"京都府京都市左京区吉田本町","lat":35.0273761,"lng":135.77984967,"geo_status":"db","era":"大正3","year":1914,"year_source":"db","year_min":1914,"year_max":1914,"year_label":null,"structure":"煉瓦造２階建，瓦葺，建築面積732㎡","structure_material":"煉瓦造２階建","registered":"1998.09.02(平成10.09.02)","register_no":"26 － 0020","desc":"京都帝大拡張期の代表的建築で，陳列館としての記念碑的性格を有する。ブロークンペディメントや楕円形の窓などネオバロックに傾斜しながらも，細部装飾にはセセッション的意匠が認められ大正期建築の特徴をも示す。京大営繕の山本治兵衛と永瀬狂三の設計。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000739"},{"id":"00015474","register_sub_id":"101","register_pk":"533489","name":"京都府立堂本印象美術館本館","kana":"きょうとふりつどうもといんしょうびじゅつかんほんかん","category":"文化福祉","subcategory":"建築物","type_guess":"博物館","type_guess_confidence":"high","period":"昭和後","pref":"京都府","address":"京都府京都市北区平野上柳町26-3他","lat":35.03513889,"lng":135.72601111,"geo_status":"db","era":"昭和41年／昭和40年代改修・同45年増築","year":1966,"year_source":"db","year_min":1966,"year_max":1966,"year_label":null,"structure":"鉄筋コンクリート造地上3階地下1階建、建築面積565㎡","structure_material":"鉄筋コンクリート造地上3階地下1階建","registered":"2025.08.06(令和7.08.06)","register_no":"26 - 0689","desc":"衣笠山東麓に位置し、日本画家堂本印象の作品を収蔵展示する美術館の本館。鉄筋コンクリート造地上３階地下1階建で、モダンな白色の外壁をレリーフで華やかに飾る。独創的な外観とともにスロープで廻る展示室など内外ともに印象の趣向を強く反映した美術館。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015474"},{"id":"00015475","register_sub_id":"101","register_pk":"533490","name":"京都府立堂本印象美術館山のアトリエ","kana":"きょうとふりつどうもといんしょうびじゅつかんやまのあとりえ","category":"文化福祉","subcategory":"建築物","type_guess":"博物館","type_guess_confidence":"high","period":"昭和中","pref":"京都府","address":"京都府京都市北区平野上柳町26-2","lat":35.03518889,"lng":135.72558611,"geo_status":"db","era":"昭和25年頃／昭和39年移築、平成3年改修","year":1950,"year_source":"db","year_min":1950,"year_max":1950,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積39㎡","structure_material":"木造平屋建","registered":"2025.08.06(令和7.08.06)","register_no":"26 - 0690","desc":"最高裁判所大法廷の壁画製作用に建てた堂本印象の作業場。木造平屋建切妻造桟瓦葺で、東に玄関を付す。内部は一室の板敷で天井は船底状に張り、内壁とともに合板張仕上。南面全面にガラス窓と欄間を開け、多くの自然光を内部に取入れる大作制作用のアトリエ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015475"},{"id":"00006384","register_sub_id":"101","register_pk":"107367","name":"対岳文庫","kana":"たいがくぶんこ","category":"文化福祉","subcategory":"建築物","type_guess":"博物館","type_guess_confidence":"high","period":"昭和前","pref":"京都府","address":"京都府京都市左京区岩倉上蔵町100","lat":35.07843876,"lng":135.78313083,"geo_status":"db","era":"昭和3","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"鉄筋コンクリート造平屋建、瓦葺、建築面積69㎡","structure_material":"鉄筋コンクリート造平屋建","registered":"2007.10.02(平成19.10.02)","register_no":"26 － 0266","desc":"鉄筋コンクリート造平屋建で、桟瓦葺。東西棟の主屋に切妻妻入の玄関を突出し、外壁は上部をスクラッチタイル貼とし、腰を洗出しとする。内部は陳列室と収蔵室に分かれ、床板敷で、壁を板張とする。簡潔で軽快な意匠で、武田五一の手になる小品の好例である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006384"},{"id":"00009337","register_sub_id":"101","register_pk":"194130","name":"田村家住宅離れ（旧鈴木医院）","kana":"たむらけじゅうたくはなれ（きゅうすずきいいん）","category":"文化福祉","subcategory":"建築物","type_guess":"病院・診療","type_guess_confidence":"high","period":"大正","pref":"京都府","address":"京都府長岡京市長法寺南谷11","lat":34.93165841,"lng":135.67982681,"geo_status":"db","era":"大正14年","year":1925,"year_source":"db","year_min":1925,"year_max":1925,"year_label":null,"structure":"木造2階建、瓦葺、建築面積61㎡","structure_material":"木造2階建","registered":"2012.08.13(平成24.08.13)","register_no":"26 － 0410","desc":"丹波街道沿いの敷地南寄りに建つ。建築面積六一平方メートル、木造二階建、入母屋造桟瓦葺。一階は東面北端に玄関を構え、診察室などを配する。東面と南面は上下階に同意匠のガラス窓を建て、統一感のある外観とする。座敷の造作も丁寧で開放的な和風住宅。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009337"},{"id":"00013586","register_sub_id":"101","register_pk":"504949","name":"日の出湯","kana":"ひのでゆ","category":"文化福祉","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"京都府","address":"京都府舞鶴市字東吉原45他","lat":35.45595,"lng":135.32961944,"geo_status":"db","era":"大正6年／昭和29年改修","year":1917,"year_source":"db","year_min":1917,"year_max":1917,"year_label":null,"structure":"木造2階建、瓦葺、建築面積122㎡","structure_material":"木造2階建","registered":"2021.02.04(令和3.02.04)","register_no":"26 － 0614","desc":"西舞鶴に所在する公衆浴場。道路に西面して建つ切妻造平入で、南を銭湯、北を住居部とする。銭湯は中央に番台を構えて南北に男女を分け、浴場は中心に浴槽、周囲に洗場を配す。二階には上質な床付の座敷を配すなど、戦前の町家風銭湯建築の有様を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013586"},{"id":"00012755","register_sub_id":"101","register_pk":"367658","name":"松井家住宅主屋（旧中井産院）","kana":"まついけじゅうたくしゅおく（きゅうなかいさんいん）","category":"文化福祉","subcategory":"建築物","type_guess":"主屋・住宅","type_guess_confidence":"high","period":"昭和前","pref":"京都府","address":"京都府京都市伏見区深草稲荷榎木橋町9","lat":34.96934778,"lng":135.77112,"geo_status":"db","era":"昭和5年","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"木造2階建、スレート葺及び瓦葺、建築面積94㎡","structure_material":"木造2階建","registered":"2019.03.29(平成31.03.29)","register_no":"26 － 581","desc":"伏見稲荷界隈の角地にあり、伏見街道に西面する洋館と、その背面の和館からなる。洋館は布目タイル張に縦長窓を並べた事務所風の外観、和館は切妻造の総二階建である。両館南端に土間を通して中間を中庭とするなど、表屋造の構成を踏襲した近代の医院兼住宅。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012755"},{"id":"00000060","register_sub_id":"101","register_pk":"101050","name":"南座","kana":"みなみざ","category":"文化福祉","subcategory":"建築物","type_guess":"娯楽","type_guess_confidence":"high","period":"昭和前","pref":"京都府","address":"京都府京都市東山区四条通大和大路西入中之町198","lat":35.00349866,"lng":135.77236398,"geo_status":"db","era":"昭和4","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"鉄骨鉄筋コンクリート造・鉄骨造地上4階地下1階建、瓦葺、建築面積1797㎡","structure_material":"鉄骨鉄筋コンクリート造・鉄骨造地上4階地下1階建","registered":"1996.12.20(平成8.12.20)","register_no":"26 － 0001","desc":"桃山風の意匠を凝らした劇場建築で，総客席数1500余の大劇場を収容する。平成２年から３年にかけて改修が行われ，外観は竣工当時の姿に復元された。演劇の中心地の一つとして，また都市のランドマークとして，広く親しまれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000060"},{"id":"00002295","register_sub_id":"101","register_pk":"103285","name":"八坂倶楽部","kana":"やさかくらぶ","category":"文化福祉","subcategory":"建築物","type_guess":"会館","type_guess_confidence":"high","period":"大正","pref":"京都府","address":"京都府京都市東山区祇園町南側570-2","lat":35.001175,"lng":135.775574,"geo_status":"db","era":"大正2","year":1913,"year_source":"db","year_min":1913,"year_max":1913,"year_label":null,"structure":"木造2階建、瓦葺、建築面積746㎡","structure_material":"木造2階建","registered":"2001.08.28(平成13.08.28)","register_no":"26 － 0087","desc":"木造２階建，入母屋造・瓦葺の大屋根を架けた建物で，敷地南奥に建つ。北面西側に軒唐破風付の玄関を設け，東面と南面から庭園を望む。１階は特等客向けの待合・点茶などに用いられ，２階は広大な１３２畳敷の客席と舞台からなる広壮な舞台座敷としている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002295"},{"id":"00000877","register_sub_id":"101","register_pk":"101867","name":"陽明文庫虎山荘","kana":"ようめいぶんここざんそう","category":"文化福祉","subcategory":"建築物","type_guess":"博物館","type_guess_confidence":"high","period":"昭和前","pref":"京都府","address":"京都府京都市右京区宇多野福王子町50","lat":35.03118221,"lng":135.70986929,"geo_status":"db","era":"昭和17","year":1942,"year_source":"db","year_min":1942,"year_max":1942,"year_label":null,"structure":"木造平屋建，瓦葺，建築面積393㎡","structure_material":"木造平屋建","registered":"1998.10.09(平成10.10.09)","register_no":"26 － 0030","desc":"陽明文庫所蔵品の閲覧を目的として建てられた数寄屋造りの別荘建築。主屋部分と客殿部分から構成され，内部に茶室（滴庵）などを持つ。伝統的な構法の中にも設計者である長谷部鋭吉による新たな試みが随所になされ，細部にも見るべきものがある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000877"},{"id":"00000876","register_sub_id":"101","register_pk":"101866","name":"陽明文庫事務所","kana":"ようめいぶんこじむしょ","category":"文化福祉","subcategory":"建築物","type_guess":"博物館","type_guess_confidence":"high","period":"昭和前","pref":"京都府","address":"京都府京都市右京区宇多野上ノ谷町1-2","lat":35.03175599,"lng":135.71010738,"geo_status":"db","era":"昭和13","year":1938,"year_source":"db","year_min":1938,"year_max":1938,"year_label":null,"structure":"木造平屋建，瓦葺，建築面積159㎡","structure_material":"木造平屋建","registered":"1998.10.09(平成10.10.09)","register_no":"26 － 0029","desc":"木造平屋建ての事務所建築。第一文庫，第二文庫と並んで配置されている。簡素な意匠・構成になるが，玄関周りの格子状の意匠，暖炉の煙突などに特徴が見られ，全体として洋風とも和風ともつかない特色あるデザインである。設計は長谷部鋭吉。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000876"},{"id":"00000874","register_sub_id":"101","register_pk":"101864","name":"陽明文庫第一文庫","kana":"ようめいぶんこだいいちぶんこ","category":"文化福祉","subcategory":"建築物","type_guess":"博物館","type_guess_confidence":"high","period":"昭和前","pref":"京都府","address":"京都府京都市右京区鳴滝宇多野谷２","lat":35.03161346,"lng":135.70971315,"geo_status":"db","era":"昭和13","year":1938,"year_source":"db","year_min":1938,"year_max":1938,"year_label":null,"structure":"鉄筋コンクリート造平屋建，瓦葺，建築面積73㎡","structure_material":"鉄筋コンクリート造平屋建","registered":"1998.10.09(平成10.10.09)","register_no":"26 － 0027","desc":"近衛家に伝わる古文書・美術品などを収める収蔵庫。当時の近衛家所有地の一角に建てられた。収蔵品の重要性に鑑み，湿度管理などを意識して設計されている。土蔵風であるが，ＲＣによる堅牢な構造である。設計は長谷部鋭吉，大工棟梁は俣野忠蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000874"},{"id":"00000875","register_sub_id":"101","register_pk":"101865","name":"陽明文庫第二文庫","kana":"ようめいぶんこだいにぶんこ","category":"文化福祉","subcategory":"建築物","type_guess":"博物館","type_guess_confidence":"high","period":"昭和前","pref":"京都府","address":"京都府京都市右京区鳴滝宇多野谷２","lat":35.0316302,"lng":135.70988057,"geo_status":"db","era":"昭和15","year":1940,"year_source":"db","year_min":1940,"year_max":1940,"year_label":null,"structure":"鉄筋コンクリート造２階建，瓦葺，建築面積121㎡","structure_material":"鉄筋コンクリート造２階建","registered":"1998.10.09(平成10.10.09)","register_no":"26 － 0028","desc":"近衛家が所有する美術品等を収める収蔵庫。第一文庫と同じく湿度管理，耐震耐火などを意識して建てられたが，厳しい資材事情から床下吹き放ちを断念するなど設計・仕様が異なっている。第一文庫と同じく設計は長谷部鋭吉，大工棟梁は俣野忠蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000875"},{"id":"00012389","register_sub_id":"101","register_pk":"531713","name":"若の湯","kana":"わかのゆ","category":"文化福祉","subcategory":"建築物","type_guess":"門・塀","type_guess_confidence":"low","period":"大正","pref":"京都府","address":"京都府舞鶴市字本小字本町59他","lat":35.44853056,"lng":135.3275,"geo_status":"db","era":"大正12年／昭和15年・同49年改修","year":1923,"year_source":"db","year_min":1923,"year_max":1923,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積157㎡、塀付","structure_material":"木造平屋建","registered":"2018.05.10(平成30.05.10)","register_no":"26-573","desc":"西舞鶴市街にある公衆浴場。奥行の狭い敷地中央に切妻造妻入の玄関棟を構え、左右に男女の各浴場棟を接続し、玄関の左右には塀を延ばす。タイル張と洗出し壁を併用しつつ創作的な洋風意匠でまとめた華やかな外観で、近代舞鶴の発展と賑わいを伝えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012389"},{"id":"00006743","register_sub_id":"101","register_pk":"107726","name":"旧建部歯科医院","kana":null,"category":"文化福祉","subcategory":"建築物","type_guess":"病院・診療","type_guess_confidence":"high","period":"昭和中","pref":"京都府","address":"京都府京都市左京区下鴨松ノ木町2-2","lat":35.04181903,"lng":135.77070217,"geo_status":"db","era":"昭和28","year":1953,"year_source":"db","year_min":1953,"year_max":1953,"year_label":null,"structure":"鉄筋コンクリート造2階建、建築面積48㎡","structure_material":"鉄筋コンクリート造2階建","registered":"2007.12.05(平成19.12.05)","register_no":"26 － 0267","desc":"増田友也の設計になり「診療室をもつ小住宅」として発表される。東西６．５ｍ南北６．４ｍ規模で、４隅に柱を置き、屋根を片流れとし、南側を２階建の居住部、北側を診察室とし、診察室東面に縦ルーバーを嵌める。戦後鉄筋コンクリート造小住宅の好例である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006743"},{"id":"00005495","register_sub_id":"101","register_pk":"106483","name":"板井原公民館","kana":"いたいばらこうみんかん","category":"文化福祉","subcategory":"建築物","type_guess":"会館","type_guess_confidence":"high","period":"昭和前","pref":"鳥取県","address":"鳥取県八頭郡智頭町大字市瀬","lat":35.29107058,"lng":134.24917528,"geo_status":"db","era":"昭和前期／昭和29曳家","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造2階建、鉄板葺、建築面積36㎡","structure_material":"木造2階建","registered":"2006.03.27(平成18.03.27)","register_no":"31 － 0100","desc":"向山神社境内の東隣にある。木造２階建，切妻造，鉄板葺で，西妻面に切妻造の玄関を設け，外壁は下見板張であるが，上部の軒下を漆喰塗とする。１階は，前面に梁を架け，広く間口を開放できる構造とし，舞台を兼用している。２階は床付８畳と前室４畳からなる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005495"},{"id":"00013881","register_sub_id":"101","register_pk":"507839","name":"旧吉田医院","kana":"きゅうよしだいいん","category":"文化福祉","subcategory":"建築物","type_guess":"病院・診療","type_guess_confidence":"high","period":"昭和中","pref":"鳥取県","address":"鳥取県鳥取市瓦町504他","lat":35.49648611,"lng":134.22709167,"geo_status":"db","era":"昭和27年","year":1952,"year_source":"db","year_min":1952,"year_max":1952,"year_label":null,"structure":"土蔵造2階地下1階建、瓦葺、建築面積113㎡","structure_material":"土蔵造2階地下1階建","registered":"2021.06.24(令和3.06.24)","register_no":"31 － 0272","desc":"市街地に位置する施主設計の医院。土蔵造二階建で外壁は白漆喰で塗込め、腰を洗出に海鼠目地を施し、庇付の虫籠窓を開く。内部は一階を診療所、二階を病室とし、洋風の階段室や、東洋風の窓桟の割付など、随所に東西の様式を混在させる民藝調の意匠を見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013881"},{"id":"00013882","register_sub_id":"101","register_pk":"507840","name":"旧吉田璋也家住宅主屋","kana":"きゅうよしだしょうやけじゅうたくおもや","category":"文化福祉","subcategory":"建築物","type_guess":"主屋・住宅","type_guess_confidence":"high","period":"昭和中","pref":"鳥取県","address":"鳥取県鳥取市瓦町503他","lat":35.49649167,"lng":134.22724444,"geo_status":"db","era":"昭和28年／昭和29年頃・同35年頃増築","year":1953,"year_source":"db","year_min":1953,"year_max":1953,"year_label":null,"structure":"土蔵造2階地下1階建、瓦葺、建築面積56㎡","structure_material":"土蔵造2階地下1階建","registered":"2021.06.24(令和3.06.24)","register_no":"31 － 0273","desc":"医院の東に接続し、道路に東面して建つ。土蔵造二階建で外壁は白漆喰で塗込め、正面腰を凝灰岩積とし、庇付の大小の虫籠窓を開く。内部一階は茶の間、台所、二階は座敷等を配する。東洋風の家具や洋風天井等東西の意匠を容れた民藝調スタイルでまとめる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013882"},{"id":"00009369","register_sub_id":"101","register_pk":"194162","name":"鳥取民藝美術館","kana":"とっとりみんげいびじゅつかん","category":"文化福祉","subcategory":"建築物","type_guess":"博物館","type_guess_confidence":"high","period":"昭和中","pref":"鳥取県","address":"鳥取県鳥取市栄町651","lat":35.49612632,"lng":134.2271687,"geo_status":"db","era":"昭和32年／昭和36年増築","year":1957,"year_source":"db","year_min":1957,"year_max":1957,"year_label":null,"structure":"鉄筋コンクリート造及び鉄骨造地上2階一部地下1階建、瓦葺、建築面積81㎡","structure_material":"鉄筋コンクリート造及び鉄骨造地上2階一部地下1階建","registered":"2012.08.13(平成24.08.13)","register_no":"31 － 0173","desc":"鉄筋コンクリート造の一階に鉄骨造の二階を増築する。建築面積八一平方メートル。外壁はモルタル塗に漆喰仕上げ、腰は洗出しとして土蔵風とする。小屋組は木造で和小屋とし、切妻の置屋根に桟瓦を葺く。民藝運動に参加した施主自らが設計した民藝館。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009369"},{"id":"00011791","register_sub_id":"101","register_pk":"210807","name":"鳥取民藝美術館別館湖山池阿弥陀堂","kana":"とっとりみんげいびじゅつかんべっかんこやまいけあみだどう","category":"文化福祉","subcategory":"建築物","type_guess":"博物館","type_guess_confidence":"high","period":"昭和中","pref":"鳥取県","address":"鳥取県鳥取市三津字小狭間戸888","lat":35.518069,"lng":134.143648,"geo_status":"db","era":"昭和39年／昭和41年増築、昭和50年代改修","year":1964,"year_source":"db","year_min":1964,"year_max":1964,"year_label":null,"structure":"木造平屋建、鋼板葺、建築面積38㎡","structure_material":"木造平屋建","registered":"2017.06.28(平成29.06.28)","register_no":"31-0225","desc":"湖山池の北岸にある小山の頂上に建つ。木造平屋建で屋根は鋼板葺。池を望む展望室の背面側に水屋を介して四畳半茶室、西には二畳中板茶室を配す。構造材にクリ材を多用するほか、ケヤキ、ラワン、サクラなどを組み合わせるなど、特徴的な民芸的建築である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011791"},{"id":"00000157","register_sub_id":"101","register_pk":"101147","name":"日野町歴史民俗資料館（旧根雨公会堂）","kana":"ひのちょうれきしみんぞくしりょうかん（きゅうねうこうかいどう）","category":"文化福祉","subcategory":"建築物","type_guess":"博物館","type_guess_confidence":"high","period":"昭和前","pref":"鳥取県","address":"鳥取県日野郡日野町根雨497","lat":35.23736777,"lng":133.44270377,"geo_status":"db","era":"昭和15","year":1940,"year_source":"db","year_min":1940,"year_max":1940,"year_label":null,"structure":"木造2階建，瓦葺，建築面積473㎡","structure_material":"木造2階建","registered":"1997.05.07(平成9.05.07)","register_no":"31 － 0002","desc":"根雨の町並みを見下ろす山の中腹に建つ切妻造，妻入で，設計は岡田孝雄。間口９間，奥行１６間半，木造２階建ての大規模な公会堂である。外観は周囲の町並みに調和するように，庇を回して抑えた意匠になる。妻壁を飾るマークが文化の殿堂であることを示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000157"},{"id":"00008753","register_sub_id":"101","register_pk":"149474","name":"飛龍閣","kana":"ひりゅうかく","category":"文化福祉","subcategory":"建築物","type_guess":"会館","type_guess_confidence":"low","period":"明治","pref":"鳥取県","address":"鳥取県倉吉市仲ノ町3445-1","lat":35.42984395,"lng":133.82350896,"geo_status":"db","era":"明治37年／昭和39年・平成2年・平成20年改修","year":1904,"year_source":"converted","year_min":1904,"year_max":1904,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積203㎡","structure_material":"木造平屋建","registered":"2011.07.25(平成23.07.25)","register_no":"31 － 0164","desc":"打吹山北麓に所在する。木造平屋建、入母屋造桟瓦葺、建築面積203㎡。北面に入母屋造妻入の玄関を張り出し、左手奥に御座所、その南側に寝殿を配する。御座所はトコと違棚、平書院を構え、町並みを遠望する。洗練された意匠で、格式を感じさせる和風建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008753"},{"id":"00002811","register_sub_id":"101","register_pk":"103801","name":"中町公民館","kana":null,"category":"文化福祉","subcategory":"建築物","type_guess":"会館","type_guess_confidence":"high","period":"大正","pref":"鳥取県","address":"鳥取県八頭郡智頭町大字智頭554-1","lat":35.26938959,"lng":134.22974233,"geo_status":"db","era":"大正11以前","year":1922,"year_source":"db","year_min":1922,"year_max":1922,"year_label":null,"structure":"木造2階建、鉄板葺、建築面積140㎡","structure_material":"木造2階建","registered":"2002.06.25(平成14.06.25)","register_no":"31 － 0054","desc":"当初は個人病院として建てられたが，大正１１年より幼稚園として用いられきた。木造２階建，寄棟造・桟瓦葺で，外壁は鉄板で覆われているが，内側に下見板張を残す。外観は洋風であるが，内部は和風で纏められており，地方の洋風建築の展開を示す一事例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002811"},{"id":"00006401","register_sub_id":"101","register_pk":"107384","name":"浅野小児科医院","kana":"あさのしょうにかいいん","category":"文化福祉","subcategory":"建築物","type_guess":"病院・診療","type_guess_confidence":"high","period":"大正","pref":"島根県","address":"島根県松江市末次町74","lat":35.46961077,"lng":133.04677535,"geo_status":"db","era":"大正元／平成元改修","year":1912,"year_source":"db","year_min":1912,"year_max":1912,"year_label":null,"structure":"木造2階建、瓦葺、建築面積143㎡","structure_material":"木造2階建","registered":"2007.10.02(平成19.10.02)","register_no":"32 － 0056","desc":"道路に東面する木造２階建。間口５間の切妻造桟瓦葺である。正面北端の玄関ポーチはドリス式双子柱で飾り、上部はバルコニーとする。外壁は縦溝付ピラスターの大オーダーで３分割する。窓は２つ１組で、２階窓上にコンソールを添える。整った意匠をもつ佳品。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006401"},{"id":"00005355","register_sub_id":"101","register_pk":"106343","name":"阿須那公民館阿須那分館","kana":"あすなこうみんかんあすなぶんかん","category":"文化福祉","subcategory":"建築物","type_guess":"会館","type_guess_confidence":"high","period":"昭和中","pref":"島根県","address":"島根県邑智郡邑南町阿須那6-6","lat":34.86903386,"lng":132.61791841,"geo_status":"db","era":"昭和27","year":1952,"year_source":"db","year_min":1952,"year_max":1952,"year_label":null,"structure":"木造2階建、瓦葺、建築面積426㎡","structure_material":"木造2階建","registered":"2006.03.02(平成18.03.02)","register_no":"32 － 0045","desc":"社会教育法（昭和２４年公布）に基づく初期の公民館建築。正面１５ｍ規模，切妻造，桟瓦葺，妻入の木造２階建で，中央に講堂を配し，正面妻壁に阿須那村の村章を掲げる。いち早く公民館建設に取り組んだ村民の意気込みが感じられ，今なお広く親しまれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005355"},{"id":"00013181","register_sub_id":"101","register_pk":"368308","name":"旧島根県立博物館（島根県庁第三分庁舎）","kana":"きゅうしまねけんりつはくぶつかん（しまねけんちょうだいさんぶんちょうしゃ）","category":"文化福祉","subcategory":"建築物","type_guess":"博物館","type_guess_confidence":"high","period":"昭和中","pref":"島根県","address":"島根県松江市殿町１","lat":35.47113889,"lng":133.05155556,"geo_status":"db","era":"昭和33年／平成25年改修","year":1958,"year_source":"db","year_min":1958,"year_max":1958,"year_label":null,"structure":"鉄筋コンクリート造3階建、建築面積426㎡","structure_material":"鉄筋コンクリート造3階建","registered":"2019.12.05(令和1.12.05)","register_no":"32 － 0204","desc":"松江城の南側に建つ、鉄筋コンクリート造の旧博物館。張出した箱状の三階を三列の柱で持上げ、一、二階はベランダや吹抜けで開放的とする。景観に馴染むよう白と黒を基調とし、屋根を折板構造とする等の工夫をしつつ、設計者菊竹清訓の作風がよく現れている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013181"},{"id":"00013885","register_sub_id":"101","register_pk":"507843","name":"旧島根県立博物館新館（島根県庁第三分庁舎）","kana":"きゅうしまねけんりつはくぶつかんしんかん（しまねけんちょうだいさんぶんちょうしゃしんかん）","category":"文化福祉","subcategory":"建築物","type_guess":"博物館","type_guess_confidence":"high","period":"昭和後","pref":"島根県","address":"島根県松江市殿町1","lat":35.47116389,"lng":133.0513,"geo_status":"db","era":"昭和44年","year":1969,"year_source":"db","year_min":1969,"year_max":1969,"year_label":null,"structure":"鉄筋コンクリート造3階建、建築面積350㎡","structure_material":"鉄筋コンクリート造3階建","registered":"2021.06.24(令和3.06.24)","register_no":"32 － 0210","desc":"菊竹清訓設計の博物館新館。鉄筋コンクリート造三階建で、同設計者の本館同様、収蔵施設を上階に持上げ、下部は開放的な展示室。仕上も下層を打放し、上層を白セメントで塗分ける。壁柱の多用や大スパンをとばす梁の表現等に設計者のデザインがよく表れる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013885"},{"id":"00013886","register_sub_id":"101","register_pk":"507844","name":"島根県民会館","kana":"しまねけんみんかいかん","category":"文化福祉","subcategory":"建築物","type_guess":"会館","type_guess_confidence":"high","period":"昭和後","pref":"島根県","address":"島根県松江市殿町158","lat":35.472725,"lng":133.05303889,"geo_status":"db","era":"昭和43年","year":1968,"year_source":"db","year_min":1968,"year_max":1968,"year_label":null,"structure":"鉄筋コンクリート造一部鉄骨造地上4階地下1階建、建築面積3，893㎡、塔屋付","structure_material":"鉄筋コンクリート造一部鉄骨造地上4階地下1階建","registered":"2021.06.24(令和3.06.24)","register_no":"32 － 0211","desc":"鉄筋コンクリート造一部鉄骨造地下一階地上四階建。大ホール他展示室、会議室等を持つ総合施設。松江城大手前にあり、中心にホール、周囲に低層の会議室などを配して周辺環境に配慮。堀を挟んで建つ県庁舎のピロティとあわせて列柱を外部に並べて調和を図る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013886"},{"id":"00013887","register_sub_id":"101","register_pk":"507845","name":"島根県立図書館","kana":"しまねけんりつとしょかん","category":"文化福祉","subcategory":"建築物","type_guess":"図書館","type_guess_confidence":"high","period":"昭和後","pref":"島根県","address":"島根県松江市内中原町52","lat":35.47322778,"lng":133.04898333,"geo_status":"db","era":"昭和43年","year":1968,"year_source":"db","year_min":1968,"year_max":1968,"year_label":null,"structure":"鉄筋コンクリート造一部鉄骨造2階建、建築面積2，012㎡","structure_material":"鉄筋コンクリート造一部鉄骨造2階建","registered":"2021.06.24(令和3.06.24)","register_no":"32 － 0212","desc":"鉄筋コンクリート造一部鉄骨造二階建の図書館。菊竹清訓設計。Ｌ字形の閲覧室のモジュールを敷地形状にあわせて配置し、中央ロビーに鉄骨屋根を架け、展示や休憩スペース等を配した合理的な平面構成。外部壁柱を松江城山公園に向けて揃え、眺望を確保した。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013887"},{"id":"00013888","register_sub_id":"101","register_pk":"507846","name":"島根県立武道館","kana":"しまねけんりつぶどうかん","category":"文化福祉","subcategory":"建築物","type_guess":"会館","type_guess_confidence":"low","period":"昭和後","pref":"島根県","address":"島根県松江市内中原町52","lat":35.47191667,"lng":133.04908889,"geo_status":"db","era":"昭和45年","year":1970,"year_source":"db","year_min":1970,"year_max":1970,"year_label":null,"structure":"鉄筋コンクリート造一部鉄骨造2階建、建築面積1，704㎡","structure_material":"鉄筋コンクリート造一部鉄骨造2階建","registered":"2021.06.24(令和3.06.24)","register_no":"32 － 0213","desc":"鉄筋コンクリート造一部鉄骨造二階建で、柔剣道場四面にトレーニング場等付属施設を備えた総合体育館。菊竹清訓設計。隣接する図書館とは対照的に閉鎖的外観を持つ。二階に設けられた道場は、大空間の屋根を支える全長四〇メートルの鉄骨トラス梁が目を引く。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013888"},{"id":"00006754","register_sub_id":"101","register_pk":"107737","name":"津森内科医院","kana":"つもりないかいいん","category":"文化福祉","subcategory":"建築物","type_guess":"病院・診療","type_guess_confidence":"high","period":"昭和前","pref":"島根県","address":"島根県松江市本庄町569-1","lat":35.509724,"lng":133.128922,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"木造平屋一部2階建及び鉄筋コンクリート造平屋建、銅板葺、建築面積117㎡","structure_material":"木造平屋一部2階建及び鉄筋コンクリート造平屋建","registered":"2007.10.02(平成19.10.02)","register_no":"32 － 0055","desc":"道路西側敷地の南端に建つ木造２階建で、北側の玄関上部をバルコニーとする。背後に平屋建が続く。２階は急勾配の銅板葺半切妻屋根をＬ字に架け、東と北に妻を見せる。外壁はモルタル塗。縦長窓や２階のベイウインドウ、玄関庇などに端正な洋風意匠を見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006754"},{"id":"00007319","register_sub_id":"101","register_pk":"108301","name":"津和野町郷土館","kana":"つわのちょうきょうどかん","category":"文化福祉","subcategory":"建築物","type_guess":"会館","type_guess_confidence":"low","period":"昭和前","pref":"島根県","address":"島根県鹿足郡津和野町森村ロ127","lat":34.46558207,"lng":131.77327163,"geo_status":"db","era":"昭和17","year":1942,"year_source":"db","year_min":1942,"year_max":1942,"year_label":null,"structure":"木造2階建、瓦葺、建築面積292㎡","structure_material":"木造2階建","registered":"2008.07.08(平成20.07.08)","register_no":"32 － 0084","desc":"入母屋造妻入赤瓦葺の木造２階建で、両側面前寄りに大きく切妻造平屋建を付設、正面に切妻造の車寄を付ける。玄関ホールに階段を設け、両脇に事務室等を配し、背面側の各階を展示室とする。当初は白漆喰仕上げ。壁面に柱形等を造り出し、大きく窓を開ける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007319"},{"id":"00007544","register_sub_id":"101","register_pk":"108526","name":"花田医院診療所及び主屋","kana":"はなだいいんしんりょうじょおよびしゅおく","category":"文化福祉","subcategory":"建築物","type_guess":"病院・診療","type_guess_confidence":"high","period":"昭和前","pref":"島根県","address":"島根県江津市江津町147他","lat":35.00922648,"lng":132.22828974,"geo_status":"db","era":"昭和12","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"木造2階建、瓦葺、建築面積233㎡","structure_material":"木造2階建","registered":"2009.01.08(平成21.01.08)","register_no":"32 － 0094","desc":"本町通り西側に占める敷地に建つ。Ｔ字型に落棟を付ける寄棟造の木造２階建を中心に、その正面に入母屋造の玄関、その南側直角に半切妻造で洋風意匠になる診療所、背面に半切妻造の台所などを付設する。複雑な構成になる建物で、カーキ色の石州瓦が印象的。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007544"},{"id":"00007545","register_sub_id":"101","register_pk":"108527","name":"花田医院門及び塀","kana":"はなだいいんもんおよびへい","category":"文化福祉","subcategory":"その他工作物","type_guess":"病院・診療","type_guess_confidence":"high","period":"昭和前","pref":"島根県","address":"島根県江津市江津町147他","lat":35.00913709,"lng":132.2282167,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"門 鉄筋コンクリート造、間口2.1m、塀 木造、瓦葺、延長19m、開戸付","structure_material":"門 鉄筋コンクリート造","registered":"2009.01.08(平成21.01.08)","register_no":"32 － 0095","desc":"主屋玄関の正面に、高さ２．０ｍのＲＣ造洗出しで、頂部を段状に造る門柱を間口２．１ｍに建てる。通り沿いを生垣とし、その南端から隣地境にカーキ色の石州瓦葺の塀を設ける。方柱で、上部に横桟を渡し、壁は漆喰仕上げ腰モルタル塗とする。屋敷構えを整える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007545"},{"id":"00011552","register_sub_id":"101","register_pk":"210552","name":"福田平治・与志記念館（旧愛隣会館）","kana":"ふくだへいじ・よしきねんかん（きゅうあいりんかいかん）","category":"文化福祉","subcategory":"建築物","type_guess":"博物館","type_guess_confidence":"high","period":"昭和前","pref":"島根県","address":"島根県松江市北田町48","lat":35.47581889,"lng":133.060795,"geo_status":"db","era":"昭和6年／昭和30年頃改修、昭和34年曳家、平成28年改修","year":1931,"year_source":"db","year_min":1931,"year_max":1931,"year_label":null,"structure":"木造2階建、鉄板葺、建築面積73㎡","structure_material":"木造2階建","registered":"2017.05.02(平成29.05.02)","register_no":"32-0179","desc":"育児院の講堂・礼拝堂として建てられた。木造二階建、桁行一三メートル、梁間六メートル、切妻造で、小屋組はキングポストトラスとする。外壁はドイツ壁風のモルタル仕上げとし、礼拝室両脇に縦長窓を並べ、急勾配の屋根と共に特徴的な外観を造る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011552"},{"id":"00002813","register_sub_id":"101","register_pk":"103803","name":"岡山禁酒会館","kana":"おかやまきんしゅかいかん","category":"文化福祉","subcategory":"建築物","type_guess":"会館","type_guess_confidence":"high","period":"大正","pref":"岡山県","address":"岡山県岡山市北区丸の内1-1-157","lat":34.665112,"lng":133.930679,"geo_status":"db","era":"大正12","year":1923,"year_source":"db","year_min":1923,"year_max":1923,"year_label":null,"structure":"木造3階建、スレート葺、建築面積145㎡","structure_material":"木造3階建","registered":"2002.06.25(平成14.06.25)","register_no":"33 － 0056","desc":"岡山城西の丸西手櫓に隣接した縦長の敷地に建つ。木造３階建で，寄棟造・スレート葺（一部鉄板葺）の屋根は３階部分で腰折れ風に処理する。ドイツ壁風と白タイル張を組み合わせ垂直性を強調した正面の意匠と相俟って，市街地の歴史的景観の象徴となっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002813"},{"id":"00012816","register_sub_id":"101","register_pk":"367719","name":"邑久光明園恩賜会館","kana":"おくこうみょうえんおんしかいかん","category":"文化福祉","subcategory":"建築物","type_guess":"会館","type_guess_confidence":"high","period":"昭和前","pref":"岡山県","address":"岡山県瀬戸内市邑久町虫明6253","lat":34.66484722,"lng":134.09283583,"geo_status":"db","era":"昭和16年／平成15年改修","year":1941,"year_source":"db","year_min":1941,"year_max":1941,"year_label":null,"structure":"木造2階建、瓦葺、建築面積181㎡","structure_material":"木造2階建","registered":"2019.03.29(平成31.03.29)","register_no":"33 － 317","desc":"瀬戸内海の長島西部にあるハンセン病療養施設で、恩賜会館は敷地中央部に建つ当施設の象徴的存在。木造平屋建、半切妻造妻入で、正面は中央車寄上部の壁面を突出して三連アーチ窓を配し、両側下屋の破風を延ばして妻を二重に現すなど特徴的な造形表現とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012816"},{"id":"00012817","register_sub_id":"101","register_pk":"367720","name":"邑久光明園旧裳掛小・中学校第三分校","kana":"おくこうみょうえんきゅうもかけしょう・ちゅうがっこうだいさんぶんこう","category":"文化福祉","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"岡山県","address":"岡山県瀬戸内市邑久町虫明6253","lat":34.66484722,"lng":134.09283583,"geo_status":"db","era":"昭和14年／平成14年改修","year":1939,"year_source":"db","year_min":1939,"year_max":1939,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積213㎡","structure_material":"木造平屋建","registered":"2019.03.29(平成31.03.29)","register_no":"33 － 318","desc":"敷地東部の木尾湾を望んで北面して建つ。木造平屋建、切妻造セメント瓦葺、外壁下見板張で正面中央に切妻造の玄関を出す。正背面に欄間付の硝子窓を並べて採光を確保し、トラス小屋組と軸部を方杖で緊結して補強する。療養施設附属の学校建築の貴重な遺構。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012817"},{"id":"00012820","register_sub_id":"101","register_pk":"367723","name":"邑久光明園瀬溝桟橋","kana":"おくこうみょうえんせみぞさんばし","category":"文化福祉","subcategory":"土木構造物","type_guess":"その他","type_guess_confidence":"low","period":"昭和中","pref":"岡山県","address":"岡山県瀬戸内市邑久町虫明6253","lat":34.66484722,"lng":134.09283583,"geo_status":"db","era":"昭和24年／昭和46年・平成16年改修","year":1949,"year_source":"db","year_min":1949,"year_max":1949,"year_label":null,"structure":"石造、延長11m","structure_material":"石造","registered":"2019.03.29(平成31.03.29)","register_no":"33 － 321","desc":"施設西部の官舎区にある、対岸に本土を望む波止場の埠頭。花崗岩の谷積、幅2･8メートル、長さ10メートル、高さ1･5メートルの規模で、石積頂部にコンクリートを打設する。島と本土を結んだ職員用の船着場で、昭和期における療養施設の構成を伝えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012820"},{"id":"00012819","register_sub_id":"101","register_pk":"367722","name":"邑久光明園物資運搬斜路","kana":"おくこうみょうえんぶっしうんぱんしゃろ","category":"文化福祉","subcategory":"土木構造物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"岡山県","address":"岡山県瀬戸内市邑久町虫明6253","lat":34.66484722,"lng":134.09283583,"geo_status":"db","era":"昭和13年","year":1938,"year_source":"db","year_min":1938,"year_max":1938,"year_label":null,"structure":"コンクリート造、延長45m","structure_material":"コンクリート造","registered":"2019.03.29(平成31.03.29)","register_no":"33 － 320","desc":"敷地南部の波止場の西斜面にある、中央部高台の施設に物資を引上げるためのトロッコ軌道。コンクリート造、幅2･7メートル、長さ45メートル、高低差23メートルの規模で、北に軌道、南に階段を設ける。昭和期の鋼索式の傾斜地輸送設備として貴重な遺構。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012819"},{"id":"00012818","register_sub_id":"101","register_pk":"367721","name":"邑久光明園奉安殿","kana":"おくこうみょうえんほうあんでん","category":"文化福祉","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"岡山県","address":"岡山県瀬戸内市邑久町虫明6253","lat":34.66484722,"lng":134.09283583,"geo_status":"db","era":"昭和18年／平成21年改修","year":1943,"year_source":"db","year_min":1943,"year_max":1943,"year_label":null,"structure":"鉄筋コンクリート造平屋建、銅板葺、建築面積2.1㎡","structure_material":"鉄筋コンクリート造平屋建","registered":"2019.03.29(平成31.03.29)","register_no":"33 － 319","desc":"敷地北部の高台に南面して建つ。鉄筋コンクリート造、高欄付基壇に建つ切妻造銅板葺で、正面に鉄扉を備える。棟上に千木と鰹木を載せ、外壁の四隅に円柱形を表す。内部は一室で床を板敷、壁を板張、天井を格天井とする。類例の少ない療養施設附属の奉安殿。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012818"},{"id":"00002310","register_sub_id":"101","register_pk":"103300","name":"旧倉敷天文台スライディングルーフ観測室","kana":"きゅうくらしきてんもんだいすらいでぃんぐるーふかんそくしつ","category":"文化福祉","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"岡山県","address":"岡山県倉敷市福田町古新田940","lat":34.53513611,"lng":133.76969167,"geo_status":"db","era":"大正15","year":1926,"year_source":"db","year_min":1926,"year_max":1926,"year_label":null,"structure":"木造一部煉瓦造平屋建、鉄板葺、建築面積24㎡","structure_material":"木造一部煉瓦造平屋建","registered":"2001.08.28(平成13.08.28)","register_no":"33 － 0053","desc":"日本最初の民間天文台として知られる。東西４．４ｍ，南北５．３ｍの平面規模で，鉄板張の切妻屋根を破風に沿って東西に滑らせて開閉する。基礎は煉瓦造で１．１ｍと高く，上部は下見板張とし，望遠鏡の基礎は別に独立して造る。科学史上においても貴重。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002310"},{"id":"00008367","register_sub_id":"101","register_pk":"134009","name":"旧中島病院本館","kana":"きゅうなかしまびょういんほんかん","category":"文化福祉","subcategory":"建築物","type_guess":"病院・診療","type_guess_confidence":"high","period":"大正","pref":"岡山県","address":"岡山県津山市田町122","lat":35.06250221,"lng":133.99492913,"geo_status":"db","era":"大正6年／平成21年改修","year":1917,"year_source":"db","year_min":1917,"year_max":1917,"year_label":null,"structure":"木造2階建、鉄板葺一部スレート葺、建築面積127㎡","structure_material":"木造2階建","registered":"2010.09.10(平成22.09.10)","register_no":"33 － 0234","desc":"津山城西方の市街地に所在。木造２階建で、東正面にポーチを付け、その屋根をドーム状につくる。当初はスレート葺で、ドーム部分に名残を留める。壁は小豆色のモルタル掻き落としで、コリント式の柱や窓飾り等を人造石とする。城下の町並に彩りを添える洋風建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008367"},{"id":"00005504","register_sub_id":"101","register_pk":"106492","name":"定金家住宅主屋","kana":"さだかねけじゅうたくしゅおく","category":"文化福祉","subcategory":"建築物","type_guess":"主屋・住宅","type_guess_confidence":"high","period":"大正","pref":"岡山県","address":"岡山県浅口市金光町大谷229-14","lat":34.54053663,"lng":133.62318777,"geo_status":"db","era":"大正6頃","year":1917,"year_source":"db","year_min":1917,"year_max":1917,"year_label":null,"structure":"木造2階建、瓦葺、建築面積90㎡","structure_material":"木造2階建","registered":"2006.03.27(平成18.03.27)","register_no":"33 － 0112","desc":"東を正面として建つ。木造２階建で，東半が洋館，西半が和風住宅になる。洋館は正面中央の玄関を境に左右対称とし，スティックスタイル風の外観で，縦長窓の上を櫛形ペディメントを飾り，妻飾はハンマービームトラスを模す。調和のとれた意匠をもつ洋風建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005504"},{"id":"00000896","register_sub_id":"101","register_pk":"101886","name":"津山基督教図書館","kana":"つやまきりすときょうとしょかん","category":"文化福祉","subcategory":"建築物","type_guess":"図書館","type_guess_confidence":"high","period":"大正","pref":"岡山県","address":"岡山県津山市山下98-1","lat":35.06078343,"lng":134.00450387,"geo_status":"db","era":"大正15","year":1926,"year_source":"db","year_min":1926,"year_max":1926,"year_label":null,"structure":"木造３階建，銅板葺，建築面積230㎡","structure_material":"木造３階建","registered":"1998.10.09(平成10.10.09)","register_no":"33 － 0020","desc":"津山城跡の前面の角地に建つ。内村鑑三の弟子森本慶三が創設した建物で，設計は桜庭駒五郎。イオニア式の壁付柱を持ちゲーブルを設けた南面中央入口部の構え，東面にある時計付の塔屋，壁面各所の浮き彫り等に特徴がある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000896"},{"id":"00001645","register_sub_id":"101","register_pk":"102635","name":"永井家住宅主屋","kana":"ながいけじゅうたくしゅおく","category":"文化福祉","subcategory":"建築物","type_guess":"主屋・住宅","type_guess_confidence":"high","period":"大正","pref":"岡山県","address":"岡山県和気郡和気町和気378","lat":34.79939062,"lng":134.14581307,"geo_status":"db","era":"大正5","year":1916,"year_source":"db","year_min":1916,"year_max":1916,"year_label":null,"structure":"木造2階建、瓦葺、建築面積93㎡","structure_material":"木造2階建","registered":"2000.04.28(平成12.04.28)","register_no":"33 － 0047","desc":"吉井川と金剛川の合流点近くに位置し，県道に南面して建つ。桁行５間，梁行４間半規模の総２階建，桟瓦葺寄棟造，ドイツ下見の洋館で，東南隅に角塔を建てる。歯科診療所として建築され，地元では最初期の西洋館として親しまれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001645"},{"id":"00012815","register_sub_id":"101","register_pk":"367718","name":"長島愛生園園長官舎","kana":"ながしまあいせいえんえんちょうかんしゃ","category":"文化福祉","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"岡山県","address":"岡山県瀬戸内市邑久町虫明6539","lat":34.66484722,"lng":134.09283583,"geo_status":"db","era":"昭和5年","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積163㎡","structure_material":"木造平屋建","registered":"2019.03.29(平成31.03.29)","register_no":"33 － 316","desc":"敷地西部の官舎区の南端に西面して建つ。寄棟造桟瓦葺の平屋建で、北端に切妻造妻入の玄関付洋館を設ける。洋館に応接間と客座敷を設け、主体部に三室を並べて前後に廊下を通し、西南隅に水回りをまとめる。昭和期における和洋館併設の中流住宅の好例を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012815"},{"id":"00016725","register_sub_id":"101","register_pk":"579209","name":"長島愛生園汽缶場","kana":"ながしまあいせいえんきかんば","category":"文化福祉","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"岡山県","address":"岡山県瀬戸内市邑久町虫明6539","lat":34.680201,"lng":134.249572,"geo_status":"db","era":"昭和5年／昭和37年増築","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"鉄筋コンクリート造平屋建、人工スレート葺、建築面積224㎡","structure_material":"鉄筋コンクリート造平屋建","registered":"2026.07.09(令和8.07.09)","register_no":"33 - 0394","desc":"敷地中央の平地に位置する温熱供給施設。鉄筋コンクリート造平屋建人工スレート葺で西面入口に庇を付し、北西に宿直棟を突出。内部は土間で、小屋組は鉄骨のトラスとする。大屋根頂部に越屋根を設けた妻面が特徴的な姿で、愛生園の歴史的な景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016725"},{"id":"00016723","register_sub_id":"101","register_pk":"579207","name":"長島愛生園旧患者売店","kana":"ながしまあいせいえんきゅうかんじゃばいてん","category":"文化福祉","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"岡山県","address":"岡山県瀬戸内市邑久町虫明6539","lat":34.680435,"lng":134.249967,"geo_status":"db","era":"昭和5年／昭和中期増築、平成前期・令和5年改修","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"木造平屋建、セメント瓦葺、建築面積98㎡","structure_material":"木造平屋建","registered":"2026.07.09(令和8.07.09)","register_no":"33 - 0392","desc":"瀬戸内海の長島中央部にあるハンセン病療養施設の患者用の旧売店。敷地中央の高台に南面して建つ、平屋建切妻造セメント瓦葺で東に落棟の増築棟を延ばす。外壁ドイツ下見板張、軒廻り漆喰塗。正面軒の切妻破風と漆喰レリーフが外観のアクセントとなる旧売店。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016723"},{"id":"00012811","register_sub_id":"101","register_pk":"367714","name":"長島愛生園旧事務本館","kana":"ながしまあいせいえんきゅうじむほんかん","category":"文化福祉","subcategory":"建築物","type_guess":"会館","type_guess_confidence":"low","period":"昭和前","pref":"岡山県","address":"岡山県瀬戸内市邑久町虫明6539","lat":34.66484722,"lng":134.09283583,"geo_status":"db","era":"昭和5年／昭和前期増築、平成10年・同15年改修","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"鉄筋コンクリート造2階一部平屋建及び木造平屋建、建築面積371㎡","structure_material":"鉄筋コンクリート造2階一部平屋建及び木造平屋建","registered":"2019.03.29(平成31.03.29)","register_no":"33 － 312","desc":"瀬戸内海の長島中央部にあるハンセン病療養施設。旧事務本館は施設の中心に建つ鉄筋コンクリート造二階建一部平屋建で、南面東寄りに車寄を付す。西側の翼棟は木造の増築部。正円アーチ形の車寄開口部や二階窓、大ぶりのパラペットなど表現主義の特徴を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012811"},{"id":"00012812","register_sub_id":"101","register_pk":"367715","name":"長島愛生園旧収容所","kana":"ながしまあいせいえんきゅうしゅうようじょ","category":"文化福祉","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"岡山県","address":"岡山県瀬戸内市邑久町虫明6539","lat":34.66484722,"lng":134.09283583,"geo_status":"db","era":"昭和5年／平成29年改修","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"鉄筋コンクリート造平屋建、建築面積190㎡","structure_material":"鉄筋コンクリート造平屋建","registered":"2019.03.29(平成31.03.29)","register_no":"33 － 313","desc":"北岸の波止場に建つ新規入園者の停留施設。鉄筋コンクリート造平屋建で北面中央部に玄関を出し、縦長窓を規則的に並べる。北を廊下、南を病室とし、東半の廊下沿いに診療室や浴室を設ける。束立て板張の床など昭和初期の鉄筋コンクリート工法の様相を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012812"},{"id":"00012814","register_sub_id":"101","register_pk":"367717","name":"長島愛生園旧洗濯場","kana":"ながしまあいせいえんきゅうせんたくば","category":"文化福祉","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"岡山県","address":"岡山県瀬戸内市邑久町虫明6539","lat":34.66484722,"lng":134.09283583,"geo_status":"db","era":"昭和5年","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"鉄筋コンクリート造平屋建、建築面積156㎡","structure_material":"鉄筋コンクリート造平屋建","registered":"2019.03.29(平成31.03.29)","register_no":"33 － 315","desc":"旧日出浴場南側に並んで東面して建つ。鉄筋コンクリート造平屋建、桁行5間梁間2間で、正面の柱間毎に出入口を設け、側背面に縦長窓を並べる。構造体と外壁仕上に旧状を留め、洗濯場まで鉄筋コンクリートでつくるところに内務省直轄事業の特別さが窺える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012814"},{"id":"00012813","register_sub_id":"101","register_pk":"367716","name":"長島愛生園旧日出浴場","kana":"ながしまあいせいえんきゅうひでよくじょう","category":"文化福祉","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"岡山県","address":"岡山県瀬戸内市邑久町虫明6539","lat":34.66484722,"lng":134.09283583,"geo_status":"db","era":"昭和5年／昭和30年改修・増築","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"鉄筋コンクリート造一部木造平屋建、建築面積167㎡","structure_material":"鉄筋コンクリート造一部木造平屋建","registered":"2019.03.29(平成31.03.29)","register_no":"33 － 314","desc":"敷地東部の居住区裏山東裾に東面して建つ。鉄筋コンクリート造平屋建、天井に湯気抜とトップライトを設ける。中央から南側が男湯で、北側の女湯は角屋から出入りする。戦前に珍しい鉄筋コンクリートの浴場で温水シャワーを備えるなど当園の特別さが窺える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012813"},{"id":"00016724","register_sub_id":"101","register_pk":"579208","name":"長島愛生園恵の鐘","kana":"ながしまあいせいえんめぐみのかね","category":"文化福祉","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"岡山県","address":"岡山県瀬戸内市邑久町虫明6539","lat":34.681702,"lng":134.249585,"geo_status":"db","era":"昭和10年","year":1935,"year_source":"db","year_min":1935,"year_max":1935,"year_label":null,"structure":"鉄筋コンクリート造、瓦葺、面積9.2㎡、基壇付","structure_material":"鉄筋コンクリート造","registered":"2026.07.09(令和8.07.09)","register_no":"33 - 0393","desc":"敷地中央北寄りの丘陵に位置する鐘楼。高い基壇に建つ鉄筋コンクリート造切妻造桟瓦葺の南北棟で東西面に千鳥破風を飾る。太い円柱を４本立て、ヴォールト天井の中央に鐘を吊る。和洋折衷の独特な外観で、職員と入所者が石材を運んだと伝える記念碑的な施設。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016724"},{"id":"00014672","register_sub_id":"101","register_pk":"515214","name":"林原美術館中蔵","kana":"はやしばらびじゅつかんなかぐら","category":"文化福祉","subcategory":"建築物","type_guess":"博物館","type_guess_confidence":"high","period":"明治","pref":"岡山県","address":"岡山県岡山市北区丸の内二丁目7-115","lat":34.66389444,"lng":133.93327778,"geo_status":"db","era":"明治前期／明治26年頃・同42年頃移築","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造2階建、瓦葺、建築面積148㎡","structure_material":"木造2階建","registered":"2023.08.07(令和5.08.07)","register_no":"33 - 0353","desc":"敷地北側石垣に沿って建つ土蔵３棟のうちの中央棟で、旧生坂向邸から移築されたもの。土蔵造二階建切妻造本瓦葺、外部は漆喰塗り、腰下は海鼠壁、出隅をＬ形役物瓦と平瓦の四半張で飾り、二階壁に水切瓦付の海鼠壁の帯を廻す外観意匠で町並みを形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014672"},{"id":"00014674","register_sub_id":"101","register_pk":"515216","name":"林原美術館長屋門","kana":"はやしばらびじゅつかんながやもん","category":"文化福祉","subcategory":"建築物","type_guess":"博物館","type_guess_confidence":"high","period":"江戸","pref":"岡山県","address":"岡山県岡山市北区丸の内二丁目7-115","lat":34.66360833,"lng":133.93369722,"geo_status":"db","era":"江戸末期／明治後期移築、昭和42年改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、瓦葺、建築面積148㎡","structure_material":"木造平屋建","registered":"2023.08.07(令和5.08.07)","register_no":"33 - 0355","desc":"敷地東側の道路から入った位置に東面して建つ、土蔵造入母屋造本瓦葺の長屋門。旧生坂向邸の敷地から明治末までに移築されたもの。外部は漆喰塗りで腰下は海鼠壁、柱梁にトガの良材を用いる。池田家、生坂家の遺構としても貴重で武家屋敷構えを今に伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014674"},{"id":"00014673","register_sub_id":"101","register_pk":"515215","name":"林原美術館西蔵","kana":"はやしばらびじゅつかんにしぐら","category":"文化福祉","subcategory":"建築物","type_guess":"博物館","type_guess_confidence":"high","period":"明治","pref":"岡山県","address":"岡山県岡山市北区丸の内二丁目7-115","lat":34.66391111,"lng":133.933025,"geo_status":"db","era":"明治14年／明治42年頃移築","year":1881,"year_source":"db","year_min":1881,"year_max":1881,"year_label":null,"structure":"木造2階建、瓦葺、建築面積176㎡","structure_material":"木造2階建","registered":"2023.08.07(令和5.08.07)","register_no":"33 - 0354","desc":"敷地北側石垣に沿って建つ土蔵３棟のうちの西棟。土蔵造二階建切妻造本瓦葺で、旧生坂向邸からの移築時に２階床を下げて、小屋裏へ収納棚を増設した。外部は漆喰塗り、腰下と出隅を海鼠壁で飾り、二階壁にも海鼠壁の帯を巡らす外観意匠で町並みを形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014673"},{"id":"00014671","register_sub_id":"101","register_pk":"515213","name":"林原美術館東蔵","kana":"はやしばらびじゅつかんひがしぐら","category":"文化福祉","subcategory":"建築物","type_guess":"博物館","type_guess_confidence":"high","period":"明治","pref":"岡山県","address":"岡山県岡山市北区丸の内二丁目7-115","lat":34.66400556,"lng":133.93345278,"geo_status":"db","era":"明治前期／明治42年頃移築","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造2階建、瓦葺、建築面積89㎡","structure_material":"木造2階建","registered":"2023.08.07(令和5.08.07)","register_no":"33 - 0352","desc":"敷地北側石垣の縁に沿って建つ土蔵３棟のうちの東棟で、旧生坂向邸から明治末に移築されたもの。土蔵造二階建切妻造本瓦葺、外部は漆喰塗り、腰下は平瓦四半張。膨大な貴重資料を収蔵した旧池田家文庫として貴重な建物で、武家の蔵群として町並みを形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014671"},{"id":"00014670","register_sub_id":"101","register_pk":"515212","name":"林原美術館本館","kana":"はやしばらびじゅつかんほんかん","category":"文化福祉","subcategory":"建築物","type_guess":"博物館","type_guess_confidence":"high","period":"昭和中","pref":"岡山県","address":"岡山県岡山市北区丸の内二丁目7-115","lat":34.66363889,"lng":133.93331667,"geo_status":"db","era":"昭和38年／昭和61年増築","year":1963,"year_source":"db","year_min":1963,"year_max":1963,"year_label":null,"structure":"鉄筋コンクリート造2階地下1階建、建築面積938㎡","structure_material":"鉄筋コンクリート造2階地下1階建","registered":"2023.08.07(令和5.08.07)","register_no":"33 - 0351","desc":"岡山城二の丸跡に建つ前川國男設計の鉄筋コンクリート造の美術館。中庭を中心に単位空間を連続した回遊性を重視する平面計画、外壁の焼過ぎ煉瓦とＰＣ板の採用による生産性とディテール精度の追求等、意匠的・技術的にも後の前川の作品に通じる建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014670"},{"id":"00007689","register_sub_id":"101","register_pk":"108671","name":"若竹の園保育園舎事務室棟","kana":"わかたけのそのほいくえんしゃじむしつとう","category":"文化福祉","subcategory":"建築物","type_guess":"保育・幼稚園","type_guess_confidence":"high","period":"大正","pref":"岡山県","address":"岡山県倉敷市中央1-262-1他","lat":34.59502245,"lng":133.77002383,"geo_status":"db","era":"大正14","year":1925,"year_source":"db","year_min":1925,"year_max":1925,"year_label":null,"structure":"木造平屋建、スレート葺、建築面積131㎡","structure_material":"木造平屋建","registered":"2009.04.28(平成21.04.28)","register_no":"33 － 0228","desc":"通り西側の敷地奥に中央に建つ。広い一室からなる寄棟造の保育室から北に切妻造の事務室を張り出し、さらに園門に向けて東南方向へ切妻造の玄関を設ける。屋根スレート葺で、軒先近くを緩勾配とする。玄関は入口に石積アーチを造るなど、穏やかな表情を見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007689"},{"id":"00007690","register_sub_id":"101","register_pk":"108672","name":"若竹の園保育園舎幼児保育南棟","kana":"わかたけのそのほいくえんしゃようじほいくみなみとう","category":"文化福祉","subcategory":"建築物","type_guess":"保育・幼稚園","type_guess_confidence":"high","period":"大正","pref":"岡山県","address":"岡山県倉敷市中央1-262-1他","lat":34.59484569,"lng":133.77001979,"geo_status":"db","era":"大正14","year":1925,"year_source":"db","year_min":1925,"year_max":1925,"year_label":null,"structure":"木造平屋建、スレート葺、建築面積56㎡","structure_material":"木造平屋建","registered":"2009.04.28(平成21.04.28)","register_no":"33 － 0229","desc":"事務室棟の南に位置する。南北棟の北側で東に矩折れに曲がり切妻を正面に見せる。スレート葺で、軒先を緩勾配とする。２室の保育室を南北に配し、南室東側に煉瓦敷のテラスを設けて、園庭と一体感をもたせる。装飾は少なく、簡明で優美な園舎である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007690"},{"id":"00013450","register_sub_id":"101","register_pk":"368535","name":"翁座","kana":"おきなざ","category":"文化福祉","subcategory":"建築物","type_guess":"娯楽","type_guess_confidence":"high","period":"大正","pref":"広島県","address":"広島県府中市上下町上下字岩崎2077","lat":34.69653611,"lng":133.12315833,"geo_status":"db","era":"大正14年／昭和21年増築、平成6年改修","year":1925,"year_source":"db","year_min":1925,"year_max":1925,"year_label":null,"structure":"木造2階建、瓦葺、建築面積418㎡","structure_material":"木造2階建","registered":"2020.08.17(令和2.08.17)","register_no":"34 － 0283","desc":"石州街道上下宿の東郊に位置する芝居小屋。木造二階建、切妻造桟瓦葺で、小屋組はキングポストトラス。吹抜の客席と回舞台装置付の舞台を中心に各室を配す。二階はコ字形に桟敷席と擬宝珠高欄を廻らす。歴史的な町並みの中核として親しまれる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013450"},{"id":"00015373","register_sub_id":"101","register_pk":"532497","name":"旧小野産婦人科医院","kana":"きゅうおのさんふじんかいいん","category":"文化福祉","subcategory":"建築物","type_guess":"病院・診療","type_guess_confidence":"high","period":"昭和前","pref":"広島県","address":"広島県尾道市十四日元町514-3","lat":34.40938611,"lng":133.20275556,"geo_status":"db","era":"昭和13年／昭和40年代・令和5年改修","year":1938,"year_source":"db","year_min":1938,"year_max":1938,"year_label":null,"structure":"木造3階建、鉄板葺、建築面積100㎡","structure_material":"木造3階建","registered":"2025.03.13(令和7.03.13)","register_no":"34 - 0312","desc":"尾道の中心部に位置する旧産婦人科医院。隅切した角地に建つ木造三階建寄棟造鉄板葺で一階は診察室や手術室、二階は病室、三階は居住用和室を配す。外観モルタル吹付仕上、腰は釉薬スクラッチタイル貼。庇や付柱など直線的構成で角地を強調した外観が印象的。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015373"},{"id":"00014677","register_sub_id":"101","register_pk":"515219","name":"旧村井醫院診療棟","kana":"きゅうむらいいいんしんりょうとう","category":"文化福祉","subcategory":"建築物","type_guess":"病院・診療","type_guess_confidence":"high","period":"大正","pref":"広島県","address":"広島県尾道市御調町市字市1200","lat":34.51214444,"lng":133.14733611,"geo_status":"db","era":"大正7年／昭和中期・平成24年改修","year":1918,"year_source":"db","year_min":1918,"year_max":1918,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積89㎡","structure_material":"木造平屋建","registered":"2023.08.07(令和5.08.07)","register_no":"34 - 0303","desc":"街道の交点に栄えた御調町市にある洋風医院建築。寄棟造妻入桟瓦葺の平屋建。外壁モルタル塗で下見板張・定規柱風の意匠とし、ペディメント付上下窓を並べる。内部は正面角屋を天井飾付診察室、奥にレントゲン室とし中廊下で繋ぐ。街道の歴史的景観を形成。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014677"},{"id":"00014678","register_sub_id":"101","register_pk":"515220","name":"旧村井醫院門柱","kana":"きゅうむらいいいんもんちゅう","category":"文化福祉","subcategory":"その他工作物","type_guess":"門・塀","type_guess_confidence":"high","period":"大正","pref":"広島県","address":"広島県尾道市御調町市字市1200","lat":34.51218333,"lng":133.14743889,"geo_status":"db","era":"大正7年頃／昭和中期改修","year":1918,"year_source":"db","year_min":1918,"year_max":1918,"year_label":null,"structure":"石造、間口1.9m、石柵付","structure_material":"石造","registered":"2023.08.07(令和5.08.07)","register_no":"34 - 0304","desc":"御調町市の出雲街道沿いにある洋風医院の門柱。花崗岩の角柱で正方形断面、高さ２・９メートル、頂部兜巾で首を造り、江戸切仕上とする。付設の柵は円柱親柱と鉄丸棒からなり、前栽を囲って門柱と調和する。医院表構えとなって街道の歴史的景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014678"},{"id":"00012245","register_sub_id":"101","register_pk":"353045","name":"瀧口家住宅長屋門及び診療所","kana":"たきぐちけじゅうたくながやもんおよびしんりょうじょ","category":"文化福祉","subcategory":"建築物","type_guess":"病院・診療","type_guess_confidence":"high","period":"明治","pref":"広島県","address":"広島県庄原市春田町字岩見1-1","lat":34.816159,"lng":133.045449,"geo_status":"db","era":"明治35年頃","year":1902,"year_source":"db","year_min":1902,"year_max":1902,"year_label":null,"structure":"長屋門 土蔵造2階建、瓦葺、建築面積78㎡ 診療所 土蔵造平屋建、瓦葺、建築面積74㎡","structure_material":"長屋門 土蔵造2階建","registered":"2018.03.27(平成30.03.27)","register_no":"34-254","desc":"敷地北面に建つ。二階建の長屋門と平屋建の診療所からなる。長屋門は、西側の室と二階を院長の居室や入院施設にあて、二階廊下には腰掛を設ける。診療所は、診療室や分娩室の南面に窓を開き採光を得る。明治後期の地方病院の形式をよく伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012245"},{"id":"00012241","register_sub_id":"101","register_pk":"353041","name":"瀧口家住宅納屋","kana":"たきぐちけじゅうたくなや","category":"文化福祉","subcategory":"建築物","type_guess":"主屋・住宅","type_guess_confidence":"high","period":"大正","pref":"広島県","address":"広島県庄原市春田町字岩見1-1","lat":34.815861,"lng":133.04553,"geo_status":"db","era":"大正期","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"土蔵造2階建、瓦葺、建築面積87㎡","structure_material":"土蔵造2階建","registered":"2018.03.27(平成30.03.27)","register_no":"34-250","desc":"敷地東面に建ち主屋に面して出入口を開く。建築面積八七平方メートルで西面は下屋を取り込む。一階は往診用の馬車に使う厩と、もと養蚕の作業所で、二階は飼料置き場に使用されていた。柱に栗材の曲がり材を用い地域性を示しており屋敷構成に欠かせない施設。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012241"},{"id":"00000549","register_sub_id":"101","register_pk":"101539","name":"南山資料館","kana":"なんざんしりょうかん","category":"文化福祉","subcategory":"建築物","type_guess":"博物館","type_guess_confidence":"high","period":"昭和前","pref":"広島県","address":"広島県三原市幸崎町能地3369","lat":34.33599824,"lng":133.03439619,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"木造２階建，瓦葺，建築面積85㎡","structure_material":"木造２階建","registered":"1998.04.21(平成10.04.21)","register_no":"34 － 0015","desc":"木造２階建の診療所建築。１階が診療施設，２階は接客空間とされていた。現在では１階部分を中心として，郷土出身の芸術家清水南山の資料館となっている。上部にアーチ窓を設ける正面中央の玄関が意匠上のアクセントで，洋風の建物として親しまれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000549"},{"id":"00000489","register_sub_id":"101","register_pk":"101479","name":"岩国徴古館","kana":"いわくにちょうこかん","category":"文化福祉","subcategory":"建築物","type_guess":"会館","type_guess_confidence":"low","period":"昭和前","pref":"山口県","address":"山口県岩国市横山2-7-19","lat":34.17096809,"lng":132.17717471,"geo_status":"db","era":"昭和20","year":1945,"year_source":"db","year_min":1945,"year_max":1945,"year_label":null,"structure":"煉瓦造平屋建一部2階建，瓦葺，建築面積574㎡","structure_material":"煉瓦造平屋建一部2階建","registered":"1998.01.16(平成10.01.16)","register_no":"35 － 0018","desc":"昭和１５年に財団が設立を議決，２０年３月に竣工し，２５年以降博物館となった。ドイツ古典主義の影響がみられる意匠は，低く押さえた外観，正面の角柱の列柱，内部のすそ広がりの柱等が特徴である。設計は，早稲田大学教授で岩国中学出身の佐藤武夫。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000489"},{"id":"00006706","register_sub_id":"101","register_pk":"107689","name":"岩国徴古館第一収蔵庫","kana":"いわくにちょうこかんだいいちしゅうぞうこ","category":"文化福祉","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"山口県","address":"山口県岩国市横山2-7-19","lat":34.170975,"lng":132.177139,"geo_status":"db","era":"昭和19","year":1944,"year_source":"db","year_min":1944,"year_max":1944,"year_label":null,"structure":"木造2階建、瓦葺、建築面積88㎡","structure_material":"木造2階建","registered":"2007.12.05(平成19.12.05)","register_no":"35 － 0058","desc":"徴古館の北東に位置する。桁行５間梁間３間規模、切妻造桟瓦葺の２階建土蔵で、徴古館側の西面全面に１間半幅の下屋を差し掛けて蔵前とする。錦川の氾濫に備えて高い石積基礎上に建つ。旧岩国藩主吉川家の別邸内土蔵を移設と伝え、堂々たる姿を呈する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006706"},{"id":"00007407","register_sub_id":"101","register_pk":"108389","name":"旧日下医院正門及び塀","kana":"きゅうくさかいいんせいもんおよびへい","category":"文化福祉","subcategory":"その他工作物","type_guess":"病院・診療","type_guess_confidence":"high","period":"昭和前","pref":"山口県","address":"山口県周南市土井2-1734-2","lat":34.0763029,"lng":131.77227532,"geo_status":"db","era":"昭和前期／昭和中期改修","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"正門 石造、間口10m 塀 煉瓦造、総延長117m、北門・東門付","structure_material":"正門 石造","registered":"2008.10.23(平成20.10.23)","register_no":"35 － 0066","desc":"本館正面に正門を構え、敷地周囲に塀をまわす。門柱は高さ２．５ｍの石造角柱で、頂部を球状に加工する。塀は高さ１．７ｍで、延長１１７ｍに及び、北と東面に通用門を開く。モルタル仕上げとし、基礎や笠木に御影石を使う。本館と一体感のある景観を呈する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007407"},{"id":"00007406","register_sub_id":"101","register_pk":"108388","name":"旧日下医院別館","kana":"きゅうくさかいいんべっかん","category":"文化福祉","subcategory":"建築物","type_guess":"病院・診療","type_guess_confidence":"high","period":"昭和前","pref":"山口県","address":"山口県周南市土井2-1734-2","lat":34.076134,"lng":131.772095,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造2階一部平屋建、鉄板葺、建築面積59㎡","structure_material":"木造2階一部平屋建","registered":"2008.10.23(平成20.10.23)","register_no":"35 － 0065","desc":"本館南面に建つ木造鉄板葺。東半部が２階建で、西半部は北寄りに階段を設け、南を平屋建の陸屋根とし、物干場として利用した。外壁をモルタル塗ドイツ壁とするなど、基本的に本館と共通する意匠であるが、軒まわりや幾何学的装飾の細部などに違いを見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007406"},{"id":"00007405","register_sub_id":"101","register_pk":"108387","name":"旧日下医院本館","kana":"きゅうくさかいいんほんかん","category":"文化福祉","subcategory":"建築物","type_guess":"病院・診療","type_guess_confidence":"high","period":"昭和前","pref":"山口県","address":"山口県周南市土井2-1734-2","lat":34.076221,"lng":131.772125,"geo_status":"db","era":"昭和3／昭和前期改修","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"木造2階建、瓦葺、建築面積180㎡","structure_material":"木造2階建","registered":"2008.10.23(平成20.10.23)","register_no":"35 － 0064","desc":"西面して建つ木造２階建。Ｌ字型に落棟を設ける寄棟造瓦葺。正面は中央北寄りに車寄を設け、窓を南に３ヶ所、北に２ヶ所開け、柱型を表す。外壁はモルタル塗で、２階窓下などに幾何学的な装飾を施す。セセッション風意匠になる昭和初期の建築として親しまれる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007405"},{"id":"00000710","register_sub_id":"101","register_pk":"101700","name":"クリエイティブ・スペース赤れんが（旧山口県立山口図書館書庫）","kana":"くりえいてぃぶ・すぺーすあかれんが（きゅうやまぐちけんりつやまぐちとしょかんしょこ）","category":"文化福祉","subcategory":"建築物","type_guess":"図書館","type_guess_confidence":"high","period":"大正","pref":"山口県","address":"山口県山口市中河原町76","lat":34.18030346,"lng":131.4772703,"geo_status":"db","era":"大正7","year":1918,"year_source":"db","year_min":1918,"year_max":1918,"year_label":null,"structure":"煉瓦造２階建，建築面積141㎡","structure_material":"煉瓦造２階建","registered":"1998.09.02(平成10.09.02)","register_no":"35 － 0020","desc":"明治３６年開館の県立図書館の増設書庫として建設。妻面の仕上がりからすると更なる増築が想定されていたようである。設計は，県庁舎新築の監督にあたった藤本勝往。「赤れんがの館」として県市民に親しまれ，平成４年アートスペースとして保存再生された。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000710"},{"id":"00001955","register_sub_id":"101","register_pk":"102945","name":"四熊家住宅診療棟","kana":"しくまけじゅうたくしんりょうとう","category":"文化福祉","subcategory":"建築物","type_guess":"病院・診療","type_guess_confidence":"high","period":"明治","pref":"山口県","address":"山口県周南市土井1-1-1","lat":34.08002342,"lng":131.7729681,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造平屋建、瓦葺、建築面積35㎡","structure_material":"木造平屋建","registered":"2000.10.18(平成12.10.18)","register_no":"35 － 0037","desc":"主屋の玄関脇に前方に突出して設けられた付属棟で，約５メートル四方の診療室とその東脇の出入口・受付からなる。外壁は鼠漆喰塗りとし，縦長の上下げ窓の窓枠や隅の柱形は繰形を付けて白漆喰で仕上げ，控えめながら洋風の意匠を造っている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001955"},{"id":"00001138","register_sub_id":"101","register_pk":"102128","name":"下関市立長府博物館本館（旧長門尊攘堂）","kana":"しものせきしりつちょうふはくぶつかんほんかん（きゅうながとそんじょうどう）","category":"文化福祉","subcategory":"建築物","type_guess":"博物館","type_guess_confidence":"high","period":"昭和前","pref":"山口県","address":"山口県下関市長府川端1-2-5","lat":33.99548419,"lng":130.98237633,"geo_status":"db","era":"昭和8","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"鉄筋コンクリート造平屋建，瓦葺，建築面積315㎡","structure_material":"鉄筋コンクリート造平屋建","registered":"1999.06.07(平成11.06.07)","register_no":"35 － 0022","desc":"旧功山寺境内にある。地元出身の桂弥一が京都の尊攘堂にならって建てたもの。鉄筋コンクリート造，石貼りの躯体に和風屋根をのせた姿には時代の特徴がよくあらわれている。屋根を２重にする外観全体の構成は国宝功山寺仏殿と似る。設計は潮見長彦と伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001138"},{"id":"00001456","register_sub_id":"101","register_pk":"102446","name":"下横瀬公民館（旧明木村立図書館）","kana":"しもよこぜこうみんかん（きゅうあきらぎそんりつとしょかん）","category":"文化福祉","subcategory":"建築物","type_guess":"会館","type_guess_confidence":"high","period":"昭和前","pref":"山口県","address":"山口県萩市明木下横瀬","lat":34.32149117,"lng":131.39334489,"geo_status":"db","era":"昭和3","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積144㎡","structure_material":"木造平屋建","registered":"1999.11.18(平成11.11.18)","register_no":"35 － 0030","desc":"村立図書館の新館を移築・増築したもので，当初は地元の小学校敷地内に建っていた。校舎との連絡用渡り廊下の一部を玄関ポーチとして利用し，そこから縦長の欄間付上げ下げ窓を左右対称に配している。村民の文化教養向上に大きく貢献した建物として貴重。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001456"},{"id":"00008581","register_sub_id":"101","register_pk":"134977","name":"日清講和記念館","kana":"にっしんこうわきねんかん","category":"文化福祉","subcategory":"建築物","type_guess":"博物館","type_guess_confidence":"high","period":"昭和前","pref":"山口県","address":"山口県下関市阿弥陀寺町5-4他","lat":33.95902544,"lng":130.94836306,"geo_status":"db","era":"昭和12年","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"鉄筋コンクリート造平屋一部地下1階建、瓦葺、建築面積138㎡","structure_material":"鉄筋コンクリート造平屋一部地下1階建","registered":"2011.01.26(平成23.01.26)","register_no":"35 － 0068","desc":"春帆楼の東南に位置し、西北を正面とする。棟の高いＲＣ造平屋建で、東寄りに地階を設ける。入母屋造妻入本瓦葺とし、玄関に庇を付ける。外観は腰石貼で、太い柱型を現し、上方に大きく矩形の窓を穿つ。組物や懸魚など伝統的な細部を配し、威風ある姿をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008581"},{"id":"00013457","register_sub_id":"101","register_pk":"368542","name":"旧北室醫院石垣","kana":"きゅうきたむろいいんいしがき","category":"文化福祉","subcategory":"その他工作物","type_guess":"門・塀","type_guess_confidence":"low","period":"大正","pref":"徳島県","address":"徳島県美馬郡つるぎ町半田字松生182-1他","lat":34.04128611,"lng":134.02589444,"geo_status":"db","era":"大正後期","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正後期","structure":"石造、総延長64m","structure_material":"石造","registered":"2020.08.17(令和2.08.17)","register_no":"36 － 0212","desc":"北の一段低くなった吉野川側の敷地を支える石垣。北西角から北辺中程まで延び、敷地形状に合わせて雁行配置とする。吉野川流域で見られる阿波の青石（緑泥片岩）を主体に、平石や角石を積上げ、隅は算木積とする。敷地北辺の屋敷景観を整える構造物。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013457"},{"id":"00013453","register_sub_id":"101","register_pk":"368538","name":"旧北室醫院主屋","kana":"きゅうきたむろいいんおもや","category":"文化福祉","subcategory":"建築物","type_guess":"主屋・住宅","type_guess_confidence":"high","period":"明治","pref":"徳島県","address":"徳島県美馬郡つるぎ町半田字松生183-1","lat":34.04109167,"lng":134.02629444,"geo_status":"db","era":"明治34年／昭和前期増築","year":1901,"year_source":"db","year_min":1901,"year_max":1901,"year_label":null,"structure":"木造2階建、瓦葺、建築面積158㎡","structure_material":"木造2階建","registered":"2020.08.17(令和2.08.17)","register_no":"36 － 0208","desc":"敷地南東に南面して建つ、漢方医時代の主屋。木造２階建、入母屋造本瓦葺で、四周に下屋を廻し、正面西寄に入母屋玄関を付し、２階壁には木瓜枠の虫籠窓を穿つ。内部は表側に薬局、診療所、床付の座敷を並べ、奥側は住居部とする。重厚かつ上質な主屋。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013453"},{"id":"00013451","register_sub_id":"101","register_pk":"368536","name":"旧北室醫院診療所","kana":"きゅうきたむろいいんしんりょうじょ","category":"文化福祉","subcategory":"建築物","type_guess":"病院・診療","type_guess_confidence":"high","period":"大正","pref":"徳島県","address":"徳島県美馬郡つるぎ町半田字松生182-1","lat":34.04107778,"lng":134.02596944,"geo_status":"db","era":"大正10年／昭和中期増築","year":1921,"year_source":"db","year_min":1921,"year_max":1921,"year_label":null,"structure":"木造2階一部平屋建、瓦葺一部銅板葺、建築面積194㎡","structure_material":"木造2階一部平屋建","registered":"2020.08.17(令和2.08.17)","register_no":"36 － 0206","desc":"吉野川南岸の敷地中央西寄に南面して建つ。木造２階建、寄棟造桟瓦葺の洋風建築で、正面に切妻破風と車寄を付す。外壁は柱や貫を現し、小壁を漆喰塗、他を板張とする。改造も少なく医療設備等も良く残り、地域医療を西洋医学で支えた当家の歴史を物語る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013451"},{"id":"00013454","register_sub_id":"101","register_pk":"368539","name":"旧北室醫院土蔵","kana":"きゅうきたむろいいんどぞう","category":"文化福祉","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"徳島県","address":"徳島県美馬郡つるぎ町半田字松生183-1","lat":34.04114722,"lng":134.02613611,"geo_status":"db","era":"明治11年","year":1878,"year_source":"db","year_min":1878,"year_max":1878,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積31㎡","structure_material":"土蔵造2階建","registered":"2020.08.17(令和2.08.17)","register_no":"36 － 0209","desc":"診療所東側に南面して建つ、漢方薬の原料等の保管蔵。土蔵造２階建、本瓦葺で、正面に桟瓦葺の深い下屋を付す。外壁は漆喰で軒裏まで塗込める。内部は板敷で、壁、天井に鉄板を張って区画し、保管棚を設ける。簡素な外観ながら、医院機能を補佐した建物。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013454"},{"id":"00013456","register_sub_id":"101","register_pk":"368541","name":"旧北室醫院土塀","kana":"きゅうきたむろいいんどべい","category":"文化福祉","subcategory":"その他工作物","type_guess":"門・塀","type_guess_confidence":"high","period":"大正","pref":"徳島県","address":"徳島県美馬郡つるぎ町半田字松生183-1","lat":34.04096667,"lng":134.0262,"geo_status":"db","era":"大正後期","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正後期","structure":"土塀、瓦葺、総延長58m","structure_material":"土塀","registered":"2020.08.17(令和2.08.17)","register_no":"36 － 0211","desc":"敷地南辺東半から東辺を囲う土塀。南辺土塀の中程を開いて端部を北側に屈折し、主屋への導入路とする。桟瓦葺、壁は漆喰塗で、南辺は腰を洗出仕上とし、要所に木製縦格子を入れた虫籠窓風の開口を穿つ。敷地南東の表構えを重厚に演出する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013456"},{"id":"00013455","register_sub_id":"101","register_pk":"368540","name":"旧北室醫院庭門及び内塀","kana":"きゅうきたむろいいんにわもんおよびうちべい","category":"文化福祉","subcategory":"その他工作物","type_guess":"門・塀","type_guess_confidence":"high","period":"昭和前","pref":"徳島県","address":"徳島県美馬郡つるぎ町半田字松生183-1","lat":34.04101111,"lng":134.02629167,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"庭門 木造、瓦葺、間口1.5m、内塀 木造、銅板葺、総延長5.4m","structure_material":"庭門 木造","registered":"2020.08.17(令和2.08.17)","register_no":"36 － 0210","desc":"主屋中程から南の土塀に至る一間棟門と板塀。門は腕木門で屋根は切妻造本瓦葺で、大棟端部に鯱を載せる。板塀は銅板葺で棟に雁振瓦を葺き、布着礎はモルタル塗で、松皮菱文を刻む。壁は大和打の竪板張で、襷桟の欄間を入れる。重厚な意匠の門と塀。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013455"},{"id":"00013452","register_sub_id":"101","register_pk":"368537","name":"旧北室醫院病棟","kana":"きゅうきたむろいいんびょうとう","category":"文化福祉","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"徳島県","address":"徳島県美馬郡つるぎ町半田字松生182-1","lat":34.04119167,"lng":134.02591667,"geo_status":"db","era":"大正10年頃","year":1921,"year_source":"db","year_min":1921,"year_max":1921,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積127㎡","structure_material":"木造平屋建","registered":"2020.08.17(令和2.08.17)","register_no":"36 － 0207","desc":"診療所北側に渡廊下を介して建つ入院病棟。木造平屋建、東西に長い寄妻造桟瓦葺で、東西に下屋を付す。内部は北に７室の病室、南に廊下を配し、南西角に水回りを突出する。病室は洋室で、板床に腰壁を廻らしベッドを置く。地方の医療施設の様相を今に伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013452"},{"id":"00014958","register_sub_id":"101","register_pk":"519218","name":"旧西野家住宅（徳島県立阿波十郎兵衛屋敷）辰巳座敷","kana":"きゅうにしのけじゅうたく（とくしまけんりつあわじゅうろべえやしき）たつみざしき","category":"文化福祉","subcategory":"建築物","type_guess":"主屋・住宅","type_guess_confidence":"high","period":"江戸","pref":"徳島県","address":"徳島県徳島市川内町宮島本浦184","lat":34.09158333,"lng":134.584,"geo_status":"db","era":"江戸末期／昭和29年移築","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、瓦葺、建築面積106㎡","structure_material":"木造平屋建","registered":"2024.03.06(令和6.03.06)","register_no":"36 - 0226","desc":"吉野川河口の川内の角地に位置し、元藍商屋敷から移築された座敷。東面寄棟造、西面入母屋造桟瓦葺平屋建で三方に庇を付す。東は土間、西は二一畳の座敷で、北面に床、棚を構え、東面は襖絵で飾る。床廻りには銘木を用い、彫物のある筆返しなど上質な意匠。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014958"},{"id":"00014959","register_sub_id":"101","register_pk":"519219","name":"旧西野家住宅（徳島県立阿波十郎兵衛屋敷）長屋門","kana":"きゅうにしのけじゅうたく（とくしまけんりつあわじゅうろべえやしき）ながやもん","category":"文化福祉","subcategory":"建築物","type_guess":"主屋・住宅","type_guess_confidence":"high","period":"江戸","pref":"徳島県","address":"徳島県徳島市川内町宮島本浦184","lat":34.09148611,"lng":134.58418611,"geo_status":"db","era":"安政2年(1855)／昭和29年移築","year":1855,"year_source":"db","year_min":1855,"year_max":1855,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積66㎡","structure_material":"木造平屋建","registered":"2024.03.06(令和6.03.06)","register_no":"36 - 0227","desc":"元藍商屋敷から移築された長屋門。敷地東辺に開く入母屋造本瓦葺の平屋建。両開板戸の中央門口を挟んで北に２室、南に１室を配す。外壁は腰を簓子下見板張とし、北寄りに出格子を配して瓦葺の小庇を付す。扉板など良材を用いた格式ある表構えで景観をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014959"},{"id":"00015513","register_sub_id":"101","register_pk":"533528","name":"貞光劇場","kana":"さだみつげきじょう","category":"文化福祉","subcategory":"建築物","type_guess":"娯楽","type_guess_confidence":"high","period":"昭和前","pref":"徳島県","address":"徳島県美馬郡つるぎ町貞光字宮下68-1他","lat":34.03806389,"lng":134.06124167,"geo_status":"db","era":"昭和7年／昭和中期改修","year":1932,"year_source":"db","year_min":1932,"year_max":1932,"year_label":null,"structure":"木造平屋一部2階建、銅板葺、建築面積430㎡","structure_material":"木造平屋一部2階建","registered":"2025.08.06(令和7.08.06)","register_no":"36 - 0229","desc":"町の中心部に位置する旧芝居小屋。切妻造銅板葺で外壁を横板張とし、正面に大スパンアーチの玄関を備え、上部に屋号と劇場名を大きく記す。一階は舞台と吹抜の客席を設け、周囲に桟敷を配し、上部の格天井に往事の広告を残す。貞光町の隆盛を示す劇場建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015513"},{"id":"00016741","register_sub_id":"101","register_pk":"579225","name":"延寿閣別館","kana":"えんじゅかくべっかん","category":"文化福祉","subcategory":"建築物","type_guess":"会館","type_guess_confidence":"low","period":"明治","pref":"香川県","address":"香川県丸亀市一番丁4-乙","lat":34.285895,"lng":133.80108,"geo_status":"db","era":"昭和8年／令和5年改修","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"木造平屋建、瓦葺一部銅板葺、建築面積117㎡","structure_material":"木造平屋建","registered":"2026.07.09(令和8.07.09)","register_no":"37 - 0495","desc":"丸亀城跡三の丸にある迎賓施設。平屋建寄棟造桟瓦葺で、北に玄関、南に続き間座敷を配し、東・南に入側の広縁を廻らす。１５畳の座敷は床柱や床板に欅を用い、幅広の杉板を張った天井に棹を吹寄に配る。良材を吟味し、讃岐平野への眺望が優れた上質な座敷棟。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016741"},{"id":"00001019","register_sub_id":"101","register_pk":"102009","name":"鎌田共済会郷土博物館（旧図書館）","kana":"かまたきょうさいかいきょうどはくぶつかん（きゅうとしょかん）","category":"文化福祉","subcategory":"建築物","type_guess":"博物館","type_guess_confidence":"high","period":"大正","pref":"香川県","address":"香川県坂出市本町1-1-24","lat":34.31332183,"lng":133.85198971,"geo_status":"db","era":"大正11","year":1922,"year_source":"db","year_min":1922,"year_max":1922,"year_label":null,"structure":"鉄筋コンクリート造３階建，建築面積444㎡","structure_material":"鉄筋コンクリート造３階建","registered":"1998.12.11(平成10.12.11)","register_no":"37 － 0018","desc":"坂出の実業家鎌田勝太郎が慈善育英各種社会教育を目的に設立した財団法人の中核施設。香川県技師富士精一監修の下，竹中工務店の設計施工になる。我が国初期の財団法人の活動事情を示す遺構で，初期の本格的鉄筋コンクリート造図書館建築としても貴重。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001019"},{"id":"00000551","register_sub_id":"101","register_pk":"101541","name":"琴平町公会堂","kana":"ことひらちょうこうかいどう","category":"文化福祉","subcategory":"建築物","type_guess":"会館","type_guess_confidence":"high","period":"昭和前","pref":"香川県","address":"香川県仲多度郡琴平町川西甲975-1","lat":34.18542776,"lng":133.81815389,"geo_status":"db","era":"昭和9","year":1934,"year_source":"db","year_min":1934,"year_max":1934,"year_label":null,"structure":"木造平屋建，瓦葺，建築面積914㎡","structure_material":"木造平屋建","registered":"1998.04.21(平成10.04.21)","register_no":"37 － 0014","desc":"金刀比羅宮の参道沿いに建つ和風を基調とした大型の公会堂で，大きく玄関棟，ホール棟，和室棟から構成される。ホール内部は近年の改修で一新されたが，入母屋造の大屋根や玄関棟，和室棟の小屋根が取り付く優雅な外観は，広く親しまれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000551"},{"id":"00005036","register_sub_id":"101","register_pk":"106026","name":"堀家時計店","kana":"ほりけとけいてん","category":"文化福祉","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"香川県","address":"香川県丸亀市西平山町98","lat":34.293236,"lng":133.79541,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"木造2階建、瓦葺、建築面積125㎡","structure_material":"木造2階建","registered":"2005.11.10(平成17.11.10)","register_no":"37 － 0282","desc":"丸亀駅の北東方に位置し，道路に北面して建つ。寄棟造，桟瓦葺の木造２階建で，正面をモルタル塗とした看板建築。もと医院で，端部など要所に柱形を現し，中央入口はやや壁面を前に突出して両脇に柱を建て，中央軒上部にはゲーブル状の装飾等を付けるのが特徴。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005036"},{"id":"00002844","register_sub_id":"101","register_pk":"103834","name":"山本医院","kana":"やまもといいん","category":"文化福祉","subcategory":"建築物","type_guess":"病院・診療","type_guess_confidence":"high","period":"大正","pref":"香川県","address":"香川県仲多度郡多度津町大通り甲1019-1","lat":34.27342865,"lng":133.7513634,"geo_status":"db","era":"大正15","year":1926,"year_source":"db","year_min":1926,"year_max":1926,"year_label":null,"structure":"木造2階建、瓦葺、建築面積97㎡","structure_material":"木造2階建","registered":"2002.06.25(平成14.06.25)","register_no":"37 － 0112","desc":"多度津町の大通りに南面して建つ。木造２階建，モルタル塗の洋風医院建築で，腰部の石張とせいの高いパラペットにより三層構成をとり，玄関部を薄く張り出して頂部を山形のゲーブル状に納めるなどの特徴があり，当地域でひときわ目立つ存在となっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002844"},{"id":"00011425","register_sub_id":"101","register_pk":"209262","name":"今治ラヂウム温泉本館","kana":"いまばりらぢうむおんせんほんかん","category":"文化福祉","subcategory":"建築物","type_guess":"会館","type_guess_confidence":"low","period":"大正","pref":"愛媛県","address":"愛媛県今治市共栄町四丁目2-8","lat":34.069915,"lng":132.998546,"geo_status":"db","era":"大正後期／昭和63改修","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正後期","structure":"鉄筋コンクリート造2階建、建築面積408㎡、塔屋及び煙突付","structure_material":"鉄筋コンクリート造2階建","registered":"2016.11.29(平成28.11.29)","register_no":"38－0115","desc":"今治の中心市街地に建つ鉄筋コンクリート造銭湯施設。陸屋根の本体中央に五角形平面に六角形平面を重ねた塔屋を掲げ、背面に八角形ドームを持つ男女浴室を並べる、極めて特異な外観を持つ。戦災を受けた今治で戦前より残る貴重なランドマークである。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011425"},{"id":"00002185","register_sub_id":"101","register_pk":"103175","name":"内之浦公会堂","kana":"うちのうらこうかいどう","category":"文化福祉","subcategory":"建築物","type_guess":"会館","type_guess_confidence":"high","period":"昭和前","pref":"愛媛県","address":"愛媛県八幡浜市保内町川之石5番耕地41","lat":33.47605737,"lng":132.38860201,"geo_status":"db","era":"昭和12","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"木造2階建、建築面積108㎡","structure_material":"木造2階建","registered":"2001.04.24(平成13.04.24)","register_no":"38 － 0016","desc":"川之石港に臨む海岸沿いに建つ地域の公会堂建築。木造２階建，道路沿い西面中央に玄関ポーチを設け，外壁はセメントモルタル洗出し仕上げとし，陸屋根造に見せる。内部は２階を畳敷きの大広間とするなど地区公会堂の性格をもつ。棟梁は那須喜八郎。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002185"},{"id":"00003471","register_sub_id":"101","register_pk":"104461","name":"愛媛県教育会館","kana":"えひめけんきょういくかいかん","category":"文化福祉","subcategory":"建築物","type_guess":"会館","type_guess_confidence":"high","period":"昭和前","pref":"愛媛県","address":"愛媛県松山市北持田町131-1","lat":33.845032,"lng":132.776794,"geo_status":"db","era":"昭和12","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"木造3階建、鉄板葺、建築面積561㎡","structure_material":"木造3階建","registered":"2003.07.01(平成15.07.01)","register_no":"38 － 0043","desc":"木造３階建で，事務室，会議室，図書室などを設ける。洋風意匠を基調とし和風装飾を組み合わせる昭和前期に特徴的な意匠を持つ。外観は垂直性をやや強調し，玄関上部には和風意匠の直截な引用が見られる。設計は県建築技師の浅香了輔。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003471"},{"id":"00002184","register_sub_id":"101","register_pk":"103174","name":"大西内科医院診療棟","kana":"おおにしないかいいんしんりょうとう","category":"文化福祉","subcategory":"建築物","type_guess":"病院・診療","type_guess_confidence":"high","period":"大正","pref":"愛媛県","address":"愛媛県四国中央市金生町下分1423","lat":34.0004503,"lng":133.58204444,"geo_status":"db","era":"大正初期","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正初期","structure":"木造平屋建、瓦葺、建築面積113㎡","structure_material":"木造平屋建","registered":"2001.04.24(平成13.04.24)","register_no":"38 － 0015","desc":"敷地の北寄りにほぼ南面して建つ。木造平屋建，下見板張の医院建築で，外壁は洋風につくるが，屋根は伝統的な入母屋造，桟瓦葺，玄関ポーチも入母屋造の伝統的な車寄とする。道路側の東面に盲のファンライトつけるなど擬洋風的意匠にも特色がある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002184"},{"id":"00007810","register_sub_id":"101","register_pk":"108791","name":"旧泉寿亭特別室棟","kana":"きゅうせんじゅていとくべつしつとう","category":"文化福祉","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"愛媛県","address":"愛媛県新居浜市立川町598-1","lat":33.90078785,"lng":133.30967259,"geo_status":"db","era":"昭和12／平成3移築改造","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積114㎡","structure_material":"木造平屋建","registered":"2009.08.07(平成21.08.07)","register_no":"38 - 0091","desc":"桁行８．６ｍ梁間１１ｍの木造平屋建。入母屋造桟瓦葺で軒先を銅板葺とし、正面に庇を掛ける切妻屋根の玄関を西面に付ける。六畳と十畳の座敷を南北に配し、四周に縁をまわす。軒まわりに丸太材を多用し、随所に竹や杉皮等をあしらう数寄屋風のつくりになる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007810"},{"id":"00004057","register_sub_id":"101","register_pk":"105047","name":"武徳殿","kana":"ぶとくでん","category":"文化福祉","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"愛媛県","address":"愛媛県新居浜市徳常町4-6","lat":33.963444,"lng":133.281128,"geo_status":"db","era":"昭和13","year":1938,"year_source":"db","year_min":1938,"year_max":1938,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積571㎡","structure_material":"木造平屋建","registered":"2004.03.02(平成16.03.02)","register_no":"38 － 0058","desc":"石造基壇の上に東西棟で建つ。切妻造，桟瓦葺の主屋根の４周に下屋を廻し，下屋付け根上に高窓を配する。外周廻りの柱上に舟肘木を載せ，内部には５０畳敷規模の剣道場と柔道場を収める。主屋根中央の千鳥破風と入母屋造車寄を重ねた正面の構えに特徴がある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004057"},{"id":"00013002","register_sub_id":"101","register_pk":"368080","name":"松山城内門","kana":"まつやまじょううちもん","category":"文化福祉","subcategory":"その他工作物","type_guess":"城郭","type_guess_confidence":"high","period":"昭和後","pref":"愛媛県","address":"愛媛県松山市丸之内1","lat":33.84559167,"lng":132.76560278,"geo_status":"db","era":"昭和42年","year":1967,"year_source":"db","year_min":1967,"year_max":1967,"year_label":null,"structure":"木造、瓦葺、間口3.2m、脇戸付","structure_material":"木造","registered":"2019.09.10(令和1.09.10)","register_no":"38 － 141","desc":"天守と玄関多聞櫓の間に建つ一重櫓門。両下造本瓦葺、一間一戸脇戸付で、外壁は天守と一連の漆喰塗及び下見板張とする。上層は渡廊下とし、両側出入口に両開きの土戸を備える。天守北側の枡形を構成し、筋鉄門と同じく天守の堅固な門構えを形成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013002"},{"id":"00012996","register_sub_id":"101","register_pk":"368074","name":"松山城北隅櫓","kana":"まつやまじょうきたすみやぐら","category":"文化福祉","subcategory":"建築物","type_guess":"城郭","type_guess_confidence":"high","period":"昭和後","pref":"愛媛県","address":"愛媛県松山市丸之内1","lat":33.84560833,"lng":132.76540278,"geo_status":"db","era":"昭和42年","year":1967,"year_source":"db","year_min":1967,"year_max":1967,"year_label":null,"structure":"木造2階建、瓦葺、建築面積64㎡","structure_material":"木造2階建","registered":"2019.09.10(令和1.09.10)","register_no":"38 － 135","desc":"ロ字形平面の連立式天守西北隅に建つ、南隅櫓と同規模の二重二階櫓。入母屋造本瓦葺で、一重目西面に千鳥破風を付す。外観、構造とも南隅櫓と同形式として天守西面の構えを左右対称に整えるとともに、多層建物が連なる天守の荘重な景観を形成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012996"},{"id":"00012998","register_sub_id":"101","register_pk":"368076","name":"松山城玄関","kana":"まつやまじょうげんかん","category":"文化福祉","subcategory":"建築物","type_guess":"城郭","type_guess_confidence":"high","period":"昭和後","pref":"愛媛県","address":"愛媛県松山市丸之内1","lat":33.84555,"lng":132.76548889,"geo_status":"db","era":"昭和42年","year":1967,"year_source":"db","year_min":1967,"year_max":1967,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積8.9㎡","structure_material":"木造平屋建","registered":"2019.09.10(令和1.09.10)","register_no":"38 － 137","desc":"玄関多聞櫓の南面西寄りに接続して建つ。式台と玄関多聞櫓に上がる階段からなり、上り勾配の向唐破風本瓦葺の屋根をかける。式台は側面に壁を設けず開放とし、正面柱上の虹梁に蟇股、小壁に筬欄間を備えるなど、天守玄関にふさわしい格調高いつくりをみせる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012998"},{"id":"00012997","register_sub_id":"101","register_pk":"368075","name":"松山城玄関多聞櫓","kana":"まつやまじょうげんかんたもんやぐら","category":"文化福祉","subcategory":"建築物","type_guess":"城郭","type_guess_confidence":"high","period":"昭和後","pref":"愛媛県","address":"愛媛県松山市丸之内1","lat":33.845625,"lng":132.76549722,"geo_status":"db","era":"昭和42年","year":1967,"year_source":"db","year_min":1967,"year_max":1967,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積78㎡","structure_material":"木造平屋建","registered":"2019.09.10(令和1.09.10)","register_no":"38 － 136","desc":"北隅櫓の東側に接続して建つ一重多聞櫓。東面入母屋造本瓦葺、東面南半に内門、南面西寄りに玄関を接続する。外壁は北隅櫓と一連の漆喰塗及び下見板張で、北面中央に庇付の石落しを付す。内部は南に廊下を通し、北に一室を配する。天守玄関部の構成を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012997"},{"id":"00012994","register_sub_id":"101","register_pk":"368072","name":"松山城小天守","kana":"まつやまじょうこてんしゅ","category":"文化福祉","subcategory":"建築物","type_guess":"城郭","type_guess_confidence":"high","period":"昭和後","pref":"愛媛県","address":"愛媛県松山市丸之内1","lat":33.84535833,"lng":132.76561667,"geo_status":"db","era":"昭和42年","year":1967,"year_source":"db","year_min":1967,"year_max":1967,"year_label":null,"structure":"木造2階建、瓦葺、建築面積98㎡","structure_material":"木造2階建","registered":"2019.09.10(令和1.09.10)","register_no":"38 － 133","desc":"ロ字形平面の連立式天守東南隅に建つ二重二階櫓。入母屋造本瓦葺で、一重目南面に千鳥破風を付す。外壁は漆喰塗、下層は腰簓子下見板張、軒裏まで塗込め、外側の東南二面に庇付の石落しを付す。天守に次ぐ規模で、天守中枢部の堂々たる構えを形成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012994"},{"id":"00012999","register_sub_id":"101","register_pk":"368077","name":"松山城十間廊下","kana":"まつやまじょうじゅっけんろうか","category":"文化福祉","subcategory":"建築物","type_guess":"城郭","type_guess_confidence":"high","period":"昭和後","pref":"愛媛県","address":"愛媛県松山市丸之内1","lat":33.84548889,"lng":132.76541944,"geo_status":"db","era":"昭和42年","year":1967,"year_source":"db","year_min":1967,"year_max":1967,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積117㎡","structure_material":"木造平屋建","registered":"2019.09.10(令和1.09.10)","register_no":"38 － 138","desc":"南隅櫓と北隅櫓をつなぐ一重多聞櫓。両下造本瓦葺、外壁は南北両櫓と一連の漆喰塗及び下見板張とし、西面三箇所に庇付の石落しを付す。内部は一室で、天井を張らず和小屋を現し、外側の西面に狭間を整然と並べる。天守防御の城郭構造の要衝となる建物である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012999"},{"id":"00013001","register_sub_id":"101","register_pk":"368079","name":"松山城筋鉄門","kana":"まつやまじょうすじがねもん","category":"文化福祉","subcategory":"その他工作物","type_guess":"城郭","type_guess_confidence":"high","period":"昭和後","pref":"愛媛県","address":"愛媛県松山市丸之内1","lat":33.845425,"lng":132.76567222,"geo_status":"db","era":"昭和42年","year":1967,"year_source":"db","year_min":1967,"year_max":1967,"year_label":null,"structure":"木造、瓦葺、間口3.0m、脇戸付","structure_material":"木造","registered":"2019.09.10(令和1.09.10)","register_no":"38 － 140","desc":"天守と小天守の間に建つ一重櫓門。両下造本瓦葺、一間一戸脇戸付で、柱の角など要所に筋鉄を打つ。外壁は天守と一連の漆喰塗及び下見板張。上層は渡廊下とし、両側出入口に両開きの土戸を備える。天守南側の枡形を構成し、天守の堅固な門構えを形成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013001"},{"id":"00015256","register_sub_id":"101","register_pk":"530680","name":"松山城太鼓門","kana":"まつやまじょうたいこもん","category":"文化福祉","subcategory":"建築物","type_guess":"城郭","type_guess_confidence":"high","period":"昭和後","pref":"愛媛県","address":"愛媛県松山市丸之内1","lat":33.84406944,"lng":132.76684167,"geo_status":"db","era":"昭和47年","year":1972,"year_source":"db","year_min":1972,"year_max":1972,"year_label":null,"structure":"木造、瓦葺、間口5.0m、建築面積21㎡、脇戸付","structure_material":"木造","registered":"2024.12.03(令和6.12.03)","register_no":"38 - 0190","desc":"昭和四七年に復元した木造櫓門。太鼓門は、筒井門とともに堅固な枡形を構成し、大手防御の要となる。石垣に挟まれる脇戸付櫓門で、上階は北続櫓と南続櫓に接続する。上階正背面には窓、正面廻りには狭間を開き、内法下を下見板張とし、他の櫓と意匠が揃う。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015256"},{"id":"00015258","register_sub_id":"101","register_pk":"530682","name":"松山城太鼓門北続櫓","kana":"まつやまじょうたいこもんきたつづきやぐら","category":"文化福祉","subcategory":"建築物","type_guess":"城郭","type_guess_confidence":"high","period":"昭和後","pref":"愛媛県","address":"愛媛県松山市丸之内1","lat":33.84410833,"lng":132.76683333,"geo_status":"db","era":"昭和47年","year":1972,"year_source":"db","year_min":1972,"year_max":1972,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積19㎡","structure_material":"木造平屋建","registered":"2024.12.03(令和6.12.03)","register_no":"38 - 0192","desc":"昭和四七年に復元した木造単層櫓。北続櫓は戦災前に既に失っていたが、残存する石垣の形状や、葛石上端の斫り状況、周囲の石段などにより続櫓が存在したと判断し、太鼓門上階の櫓から北の石垣上に南続櫓と外観意匠を揃えて復元。太鼓門の一郭を構成する続櫓。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015258"},{"id":"00015257","register_sub_id":"101","register_pk":"530681","name":"松山城太鼓門南続櫓","kana":"まつやまじょうたいこもんみなみつづきやぐら","category":"文化福祉","subcategory":"建築物","type_guess":"城郭","type_guess_confidence":"high","period":"昭和後","pref":"愛媛県","address":"愛媛県松山市丸之内1","lat":33.84403889,"lng":132.76685556,"geo_status":"db","era":"昭和47年","year":1972,"year_source":"db","year_min":1972,"year_max":1972,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積24㎡","structure_material":"木造平屋建","registered":"2024.12.03(令和6.12.03)","register_no":"38 - 0191","desc":"昭和四七年に復元した木造単層櫓。太鼓門上階の櫓から南の石垣に延び、石垣出隅に載る隅櫓。背面に出入口を設ける。屋根は太鼓門上階と一連の南北棟入母屋造本瓦葺とする。南東出隅に矩折に石落しを設け、太鼓門正面と太鼓櫓から続く一郭への射線を担う続櫓。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015257"},{"id":"00015259","register_sub_id":"101","register_pk":"530683","name":"松山城太鼓櫓","kana":"まつやまじょうたいこやぐら","category":"文化福祉","subcategory":"建築物","type_guess":"城郭","type_guess_confidence":"high","period":"昭和後","pref":"愛媛県","address":"愛媛県松山市丸之内1","lat":33.84396944,"lng":132.76649167,"geo_status":"db","era":"昭和48年","year":1973,"year_source":"db","year_min":1973,"year_max":1973,"year_label":null,"structure":"木造二階建、瓦葺、建築面積99㎡","structure_material":"木造二階建","registered":"2024.12.03(令和6.12.03)","register_no":"38 - 0193","desc":"昭和四八年に復元した木造二層隅櫓。太鼓門の西方、本丸南西隅の高石垣上に聳立。全体は矩折平面で下層は石垣に合わせ不整形平面とし、南西隅の上層も南北棟の不整形平面。西面に千鳥破風を飾り、一階の南西隅矩折と西面北端に石落しを備える厳重な構えの櫓。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015259"},{"id":"00013000","register_sub_id":"101","register_pk":"368078","name":"松山城多聞櫓","kana":"まつやまじょうたもんやぐら","category":"文化福祉","subcategory":"建築物","type_guess":"城郭","type_guess_confidence":"high","period":"昭和後","pref":"愛媛県","address":"愛媛県松山市丸之内1","lat":33.84535,"lng":132.76550833,"geo_status":"db","era":"昭和42年","year":1967,"year_source":"db","year_min":1967,"year_max":1967,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積52㎡","structure_material":"木造平屋建","registered":"2019.09.10(令和1.09.10)","register_no":"38 － 139","desc":"小天守と南隅櫓をつなぐ一重多聞櫓。両下造本瓦葺、外壁は各櫓と共通の漆喰塗及び下見板張とし、外側の南面に庇付の石落しを付す。内部は一室で、小天守側の上り階段上の出入口に両開きの土戸を備える。十間廊下と同じく天守防御の城郭構造を示す建物である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013000"},{"id":"00014299","register_sub_id":"101","register_pk":"509689","name":"松山城筒井門","kana":"まつやまじょうつついもん","category":"文化福祉","subcategory":"建築物","type_guess":"城郭","type_guess_confidence":"high","period":"昭和後","pref":"愛媛県","address":"愛媛県松山市丸之内1","lat":33.84368889,"lng":132.76679167,"geo_status":"db","era":"昭和46年","year":1971,"year_source":"db","year_min":1971,"year_max":1971,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積52㎡、脇戸付","structure_material":"木造平屋建","registered":"2022.06.29(令和4.06.29)","register_no":"38 - 0163","desc":"昭和四六年に復元された木造櫓門。筒井門は本丸下段の正門であって太鼓門一郭のさらに南方に位置する。石垣に挟まれる脇戸付櫓門で、上階は西続櫓と東続櫓に接続する。上階正背面には窓、正面廻りには狭間を開き、内法下を下見板張とし、他の櫓と意匠が揃う。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014299"},{"id":"00014301","register_sub_id":"101","register_pk":"509691","name":"松山城筒井門西続櫓","kana":"まつやまじょうつついもんにしつづきやぐら","category":"文化福祉","subcategory":"建築物","type_guess":"城郭","type_guess_confidence":"high","period":"昭和後","pref":"愛媛県","address":"愛媛県松山市丸之内1","lat":33.84364444,"lng":132.76671667,"geo_status":"db","era":"昭和46年","year":1971,"year_source":"db","year_min":1971,"year_max":1971,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積34㎡","structure_material":"木造平屋建","registered":"2022.06.29(令和4.06.29)","register_no":"38 - 0165","desc":"昭和四六年に復元された木造単層櫓。筒井門上階の櫓から石垣上に西に接続し、北背面に若干突出する。屋根は筒井門上階と一連の東西棟入母屋造とし、北突出部にも入母屋造屋根を架ける。西南隅矩折れに石落しを設け、西の戸無門とともに独特の枡形を構成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014301"},{"id":"00014300","register_sub_id":"101","register_pk":"509690","name":"松山城筒井門東続櫓","kana":"まつやまじょうつついもんひがしつづきやぐら","category":"文化福祉","subcategory":"建築物","type_guess":"城郭","type_guess_confidence":"high","period":"昭和後","pref":"愛媛県","address":"愛媛県松山市丸之内1","lat":33.84369722,"lng":132.76687778,"geo_status":"db","era":"昭和46年","year":1971,"year_source":"db","year_min":1971,"year_max":1971,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積48㎡","structure_material":"木造平屋建","registered":"2022.06.29(令和4.06.29)","register_no":"38 - 0164","desc":"昭和四六年に復元された木造単層櫓。筒井門上階の櫓から石垣上に東に接続し、折れ曲がって南正面に突出する。屋根は筒井門上階と一連の東西棟入母屋造本瓦葺とし、南突出部にも入母屋屋根を架ける。東には隠門が連続して建ち、松山城特有の縄張りを構成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014300"},{"id":"00012995","register_sub_id":"101","register_pk":"368073","name":"松山城南隅櫓","kana":"まつやまじょうみなみすみやぐら","category":"文化福祉","subcategory":"建築物","type_guess":"城郭","type_guess_confidence":"high","period":"昭和後","pref":"愛媛県","address":"愛媛県松山市丸之内1","lat":33.84536111,"lng":132.76540833,"geo_status":"db","era":"昭和42年","year":1967,"year_source":"db","year_min":1967,"year_max":1967,"year_label":null,"structure":"木造2階建、瓦葺、建築面積64㎡","structure_material":"木造2階建","registered":"2019.09.10(令和1.09.10)","register_no":"38 － 134","desc":"ロ字形平面の連立式天守西南隅に建つ二重二階櫓。入母屋造本瓦葺で、一重目西面に千鳥破風を付す。外壁は漆喰塗、下層を簓子下見板張とし、軒裏まで塗込める。外側の西北二面は下層の各隅に庇付の石落しを付し、上層に高欄を廻す。天守隅角部の構成を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012995"},{"id":"00007811","register_sub_id":"101","register_pk":"108792","name":"山根競技場観覧席","kana":"やまねきょうぎじょうかんらんせき","category":"文化福祉","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"愛媛県","address":"愛媛県新居浜市角野新田町3-2822-9他","lat":33.92348108,"lng":133.30983359,"geo_status":"db","era":"昭和3／昭和62改修","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"石造、面積4319㎡","structure_material":"石造","registered":"2009.08.07(平成21.08.07)","register_no":"38-0092","desc":"国領川に面する敷地に建設された競技場の観覧席。西端において緩やかに湾曲する延長１７０ｍ、最大２７段の玉石空積による階段状の構造物で、背面の山の斜面の擁壁を兼ねる。鉱山職員の労働奉仕により築かれた福利厚生施設で、鉱山における生活の一面を物語る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007811"},{"id":"00002181","register_sub_id":"101","register_pk":"103171","name":"和田医院診療棟","kana":"わだいいんしんりょうとう","category":"文化福祉","subcategory":"建築物","type_guess":"病院・診療","type_guess_confidence":"high","period":"明治","pref":"愛媛県","address":"愛媛県四国中央市川之江町1746","lat":34.01260548,"lng":133.57253293,"geo_status":"db","era":"明治末期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治末期","structure":"木造2階建、瓦葺、建築面積102㎡","structure_material":"木造2階建","registered":"2001.04.24(平成13.04.24)","register_no":"38 － 0012","desc":"川之江市街中心部の角地に建つ木造２階建，切妻造，下見板張の医院建築。ハンマービームを用いた妻の構成や軒下の瓔珞飾りが明治期洋館の意匠的特徴を伝えており，線の細いスティックワークにも特色がある。市内最初期の洋館として市民から親しまれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002181"},{"id":"00014426","register_sub_id":"101","register_pk":"511415","name":"足摺海底館","kana":"あしずりかいていかん","category":"文化福祉","subcategory":"建築物","type_guess":"会館","type_guess_confidence":"low","period":"昭和後","pref":"高知県","address":"高知県土佐清水市三崎4124-1先","lat":32.78596111,"lng":132.86013056,"geo_status":"db","era":"昭和46年","year":1971,"year_source":"db","year_min":1971,"year_max":1971,"year_label":null,"structure":"鉄骨造4階建、高さ24m、建築面積119㎡、連絡橋付","structure_material":"鉄骨造4階建","registered":"2022.10.31(令和4.10.31)","register_no":"39 - 0305","desc":"竜串海域公園に築かれた海中展望塔。円筒形塔部と十字形平面の展望室を、Ｈ型鋼と外殻板等の全溶接で一体化した鋼構造物。海岸とは連絡橋で接続。丸窓を多用し、頂部にアクリルブロックを廻らす。自然美の中で異彩を放つ近未来的デザインの海洋レジャー施設。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014426"},{"id":"00012850","register_sub_id":"101","register_pk":"367753","name":"海のギャラリー","kana":"うみのぎゃらりー","category":"文化福祉","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和後","pref":"高知県","address":"高知県土佐清水市竜串3908-1","lat":32.78857778,"lng":132.86579722,"geo_status":"db","era":"昭和41年／平成17年改修","year":1966,"year_source":"db","year_min":1966,"year_max":1966,"year_label":null,"structure":"鉄筋コンクリート造2階建、建築面積380㎡","structure_material":"鉄筋コンクリート造2階建","registered":"2019.03.29(平成31.03.29)","register_no":"39 － 304","desc":"竜串海岸にある林雅子設計の展示施設。鉄筋コンクリート折板構造で、二枚貝が天に開く様をモダニズムの造形表現でまとめる。内部は天窓とした大棟からの採光が水中のような幻想的な空間をつくる。デッドスペースが皆無で構造即意匠を旨とする林らしい作品。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012850"},{"id":"00011583","register_sub_id":"101","register_pk":"210512","name":"織田歯科医院主屋","kana":"おだしかいいんしゅおく","category":"文化福祉","subcategory":"建築物","type_guess":"病院・診療","type_guess_confidence":"high","period":"大正","pref":"高知県","address":"高知県高知市升形76-2","lat":33.55802306,"lng":133.52818194,"geo_status":"db","era":"大正14年／平成27年改修","year":1925,"year_source":"db","year_min":1925,"year_max":1925,"year_label":null,"structure":"鉄筋コンクリート造2階建、建築面積93㎡、塔屋付","structure_material":"鉄筋コンクリート造2階建","registered":"2017.05.02(平成29.05.02)","register_no":"39-0291","desc":"高知城の南西、旧武家地に建つ。鉄筋コンクリート造二階建、塔屋付。大オーダーの柱型を現して垂直性を強調するとともに、正面中央にはバロック風の装飾壁を立ち上げるなど、様式を混在させつつ装飾豊かに仕上げる。県内でも最初期の鉄筋コンクリート造建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011583"},{"id":"00011584","register_sub_id":"101","register_pk":"210513","name":"織田歯科医院塀","kana":"おだしかいいんへい","category":"文化福祉","subcategory":"その他工作物","type_guess":"病院・診療","type_guess_confidence":"high","period":"大正","pref":"高知県","address":"高知県高知市升形76-2","lat":33.55803111,"lng":133.52812694,"geo_status":"db","era":"大正14年／平成27年改修","year":1925,"year_source":"db","year_min":1925,"year_max":1925,"year_label":null,"structure":"鉄筋コンクリート造、延長16m、潜戸付","structure_material":"鉄筋コンクリート造","registered":"2017.05.02(平成29.05.02)","register_no":"39-0292","desc":"敷地の西辺を画す鉄筋コンクリート造の塀。主屋と共通した意匠となっており、二メートル毎に柱型を見せ、デンティルで装飾する。隅柱にはセセッションを思わせる飾りを頂部に設ける。主屋と一体となって、街区に近代的な景観を創出し、親しまれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011584"},{"id":"00003014","register_sub_id":"101","register_pk":"104004","name":"川久保家住宅診察室及び納屋","kana":"かわくぼけじゅうたくしんさつしつおよびなや","category":"文化福祉","subcategory":"建築物","type_guess":"病院・診療","type_guess_confidence":"high","period":"明治","pref":"高知県","address":"高知県香南市野市町西佐古594","lat":33.590931,"lng":133.702789,"geo_status":"db","era":"明治初期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"木造平屋建、瓦葺、建築面積52㎡","structure_material":"木造平屋建","registered":"2002.08.21(平成14.08.21)","register_no":"39 － 0064","desc":"中央に１間半の門を開く長屋門形式の建家で，正面右手に奥行３間規模の診察室を，左手に方２間に納屋を配し，納屋の西に桁行１間半の付属屋を張出す。川原石を積んだ基礎に建ち，外壁は縦板張，屋根は寄棟造とする。地方医家の診療施設遺構として貴重である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003014"},{"id":"00009227","register_sub_id":"101","register_pk":"164780","name":"旧市川医院","kana":"きゅういちかわいいん","category":"文化福祉","subcategory":"建築物","type_guess":"病院・診療","type_guess_confidence":"high","period":"大正","pref":"高知県","address":"高知県安芸郡安田町安田字東新町1672-1","lat":33.4372856,"lng":133.98013724,"geo_status":"db","era":"大正2年／平成22年改修","year":1913,"year_source":"db","year_min":1913,"year_max":1913,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積97㎡","structure_material":"木造平屋建","registered":"2012.02.23(平成24.02.23)","register_no":null,"desc":"木造平屋建、桁行18.7メートル梁間5メートル、寄棟造桟瓦葺。外壁下見板張で、玄関正面を洋風の切妻屋根とし、フィニアルを飾る。内部はレントゲン室や診察室などを1列に並べる構成とする。瀟洒な医院建築と旧柏原家住宅が並び、特徴的な景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009227"},{"id":"00001352","register_sub_id":"101","register_pk":"102342","name":"末延家住宅（旧末延堂医院）主屋","kana":"すえのぶけじゅうたく（きゅうすえのぶどういいん）しゅおく","category":"文化福祉","subcategory":"建築物","type_guess":"病院・診療","type_guess_confidence":"high","period":"昭和前","pref":"高知県","address":"高知県安芸郡芸西村和食甲1586-1","lat":33.52020536,"lng":133.81021994,"geo_status":"db","era":"昭和2","year":1927,"year_source":"db","year_min":1927,"year_max":1927,"year_label":null,"structure":"木造2階建、瓦葺、建築面積160㎡","structure_material":"木造2階建","registered":"1999.10.14(平成11.10.14)","register_no":"39 － 0003","desc":"診療所と住居を兼ねた木造２階建，下見板貼の洋館。東西棟の寄棟屋根の両端を切り落とした特徴的な屋根をもち，長屋門側の東面に居宅用の玄関を，また，南面の切妻屋根の張出しに診療所用の玄関を設ける。妻面の持送り意匠に時代的な特徴がよく表れている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001352"},{"id":"00012849","register_sub_id":"101","register_pk":"367752","name":"田所内科医院主屋","kana":"たどころないかいいんしゅおく","category":"文化福祉","subcategory":"建築物","type_guess":"病院・診療","type_guess_confidence":"high","period":"明治","pref":"高知県","address":"高知県土佐市高岡町字明官寺甲2018-2","lat":33.49596111,"lng":133.42538861,"geo_status":"db","era":"明治25年頃／昭和60年頃・平成2年頃改修","year":1892,"year_source":"db","year_min":1892,"year_max":1892,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積88㎡","structure_material":"木造平屋建","registered":"2019.03.29(平成31.03.29)","register_no":"39 － 303","desc":"市中心部にある診療所兼住宅で、敷地中央に北面して建つ。入母屋造桟瓦葺の平屋建で、北東二面に下屋を廻す。正面に濡縁、奧の前後に各4室を配し、西端に設けた座敷二室を診察室と検査室にあてる。旧市街の歴史的景観を伝える、地域に親しまれる現役の医院。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012849"},{"id":"00004837","register_sub_id":"101","register_pk":"105827","name":"寺村徳夫家住宅主屋","kana":"てらむらのりおけじゅうたくしゅおく","category":"文化福祉","subcategory":"建築物","type_guess":"主屋・住宅","type_guess_confidence":"high","period":"明治","pref":"高知県","address":"高知県安芸市土居993-1","lat":33.51812717,"lng":133.91155135,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造平屋建、瓦葺、建築面積201㎡、庭門付","structure_material":"木造平屋建","registered":"2005.07.12(平成17.07.12)","register_no":"39 － 0183","desc":"安芸土居城跡西南方の旧武家屋敷地に位置する。桁行１０間梁行５間，東西棟，寄棟造，桟瓦葺の木造平屋建で，南面玄関の西方を診療所待合，東方を２室の座敷，北側を家族の居間とし，西北にかま屋，西南に診察室を突き出す。伝統的形式による医家住居の好例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004837"},{"id":"00005933","register_sub_id":"101","register_pk":"106918","name":"嘉穂劇場","kana":"かほげきじょう","category":"文化福祉","subcategory":"建築物","type_guess":"娯楽","type_guess_confidence":"high","period":"昭和前","pref":"福岡県","address":"福岡県飯塚市飯塚281-3、280-14、280-15、282-1","lat":33.63649,"lng":130.68718,"geo_status":"db","era":"昭和6／平成16改修","year":1931,"year_source":"db","year_min":1931,"year_max":1931,"year_label":null,"structure":"木造2階建、鉄板葺、建築面積1117㎡","structure_material":"木造2階建","registered":"2006.11.29(平成18.11.29)","register_no":"40 － 0042","desc":"木造２階建の芝居小屋。鉄板葺屋根とし，正面は入母屋造，背面は切妻造とする。正面は１，２階共，両端間を除く各間に建具４枚を引違いに建込む。２階外側に手摺りを設け，妻に太鼓櫓を飾る。明治期から昭和初期に筑豊地方に建築された劇場建築の唯一の遺構。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005933"},{"id":"00015396","register_sub_id":"101","register_pk":"532520","name":"旧大學湯","kana":"きゅうだいがくゆ","category":"文化福祉","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"福岡県","address":"福岡県福岡市東区箱崎三丁目3296","lat":33.6207,"lng":130.42211667,"geo_status":"db","era":"昭和7年／昭和28年増築、同44年・令和3年改修","year":1932,"year_source":"db","year_min":1932,"year_max":1932,"year_label":null,"structure":"木造平屋建、鉄板葺、建築面積155㎡","structure_material":"木造平屋建","registered":"2025.03.13(令和7.03.13)","register_no":"40 - 0236","desc":"九州大学旧箱崎キャンパス西方にある旧銭湯。前庭に南面する切妻造平入鉄板葺で正面に半切妻造のポーチを付す。南に脱衣場、北に浴室を配し、上部吹抜中央に越屋根を設ける。下見板張の外観洋風の銭湯で、正面に大學湯の看板を掲げ、旧学生街の歴史を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015396"},{"id":"00001084","register_sub_id":"101","register_pk":"102074","name":"山辺道文化館（旧中野病院）診療棟","kana":"やまべのみちぶんかかん（きゅうなかのびょういん）しんりょうとう","category":"文化福祉","subcategory":"建築物","type_guess":"病院・診療","type_guess_confidence":"high","period":"大正","pref":"福岡県","address":"福岡県久留米市草野町草野487-1","lat":33.31816646,"lng":130.6333221,"geo_status":"db","era":"大正3頃","year":1914,"year_source":"db","year_min":1914,"year_max":1914,"year_label":null,"structure":"木造２階建，瓦葺，建築面積270㎡","structure_material":"木造２階建","registered":"1999.02.17(平成11.02.17)","register_no":"40 － 0006","desc":"久留米市の東方，草野地区に建つ大型の病院建築。煉瓦造基礎，木造下見板貼りの左右対称形の建物で，正面中央部を２階建とし，玄関上部にバルコニーを設ける。２階寄棟屋根から前面に突き出したペディメントの蟇股大瓶束風の飾りはユニーク。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001084"},{"id":"00001085","register_sub_id":"101","register_pk":"102075","name":"山辺道文化館（旧中野病院）倉庫","kana":"やまべのみちぶんかかん（きゅうなかのびょういん）そうこ","category":"文化福祉","subcategory":"建築物","type_guess":"病院・診療","type_guess_confidence":"high","period":"大正","pref":"福岡県","address":"福岡県久留米市草野町草野487-1","lat":33.31809142,"lng":130.63317456,"geo_status":"db","era":"大正3頃","year":1914,"year_source":"db","year_min":1914,"year_max":1914,"year_label":null,"structure":"木造平屋建，瓦葺，建築面積26㎡","structure_material":"木造平屋建","registered":"1999.02.17(平成11.02.17)","register_no":"40 － 0007","desc":"診療棟の背後，南西方に建つ木造平屋建，桟瓦葺，寄棟屋根の倉庫建物。診療棟と同様，下見板貼りで軒下と腰を縦羽目とする。北面の東端と南面の中央東寄りに出入口を設け，内開き窓の外側に外開きの１枚戸を付けて盗難避けとしている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001085"},{"id":"00011836","register_sub_id":"101","register_pk":"210852","name":"大隈重信記念館","kana":"おおくましげのぶきねんかん","category":"文化福祉","subcategory":"建築物","type_guess":"博物館","type_guess_confidence":"high","period":"昭和後","pref":"佐賀県","address":"佐賀県佐賀市水ヶ江二丁目360-2","lat":33.247973,"lng":130.308791,"geo_status":"db","era":"昭和41年／昭和59年・平成27年改修","year":1966,"year_source":"db","year_min":1966,"year_max":1966,"year_label":null,"structure":"鉄筋コンクリート造2階建、建築面積223㎡","structure_material":"鉄筋コンクリート造2階建","registered":"2017.06.28(平成29.06.28)","register_no":"41-0105","desc":"旧武家地にある大隈重信旧宅の東方に北面する。大隈重信生誕一二五周年を記念し、今井兼次が設計した。鉄筋コンクリート造で県木の楠の根幹と大隈のからだを曲面を多用して表現し、ステンドグラスにより室内を彩る。優れた施工技術に支えられた記念碑的建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011836"},{"id":"00014302","register_sub_id":"101","register_pk":"509692","name":"岡田三郎助アトリエ","kana":"おかださぶろうすけあとりえ","category":"文化福祉","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"佐賀県","address":"佐賀県佐賀市城内一丁目15-23","lat":33.24514722,"lng":130.30101111,"geo_status":"db","era":"明治41年頃／大正後期増築・平成30年移築","year":1908,"year_source":"db","year_min":1908,"year_max":1908,"year_label":null,"structure":"木造平屋一部2階建、鉄板葺、建築面積115㎡","structure_material":"木造平屋一部2階建","registered":"2022.06.29(令和4.06.29)","register_no":"41 - 0127","desc":"佐賀城内に移築した岡田三郎助のアトリエ。木造平屋一部二階建、金属板葺で、アトリエと女子洋画研究所からなる。内部は安定した採光を確保するため、随所に窓を穿つ。画壇の中心的サロンとなった明治期のアトリエで、初期女性洋画家教育施設としても貴重。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014302"},{"id":"00010072","register_sub_id":"101","register_pk":"196219","name":"旧村上歯科医院（中町カーサ）","kana":"きゅうむらかみしかいいん（なかまちかーさ）","category":"文化福祉","subcategory":"建築物","type_guess":"病院・診療","type_guess_confidence":"high","period":"昭和前","pref":"佐賀県","address":"佐賀県唐津市中町1868","lat":33.44729771,"lng":129.96996197,"geo_status":"db","era":"昭和8／平成25改修","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"木造2階建、瓦葺、建築面積159㎡","structure_material":"木造2階建","registered":"2014.04.25(平成26.04.25)","register_no":"41 － 0093","desc":"唐津城下の東寄りに位置する。もとは一階を和風の住宅、二階を洋風意匠の歯科診療所として使用した。外観は下見板張で二階に欄間付の縦長窓を並べ洋風とする一方で、一階の庭側に和風の縁を設けるなど、内部に呼応した外観とする。唐津中町通りの象徴的な存在。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010072"},{"id":"00001310","register_sub_id":"101","register_pk":"102300","name":"如蘭塾迎賓館","kana":"じょらんじゅくげいひんかん","category":"文化福祉","subcategory":"建築物","type_guess":"会館","type_guess_confidence":"low","period":"昭和前","pref":"佐賀県","address":"佐賀県武雄市武雄町大字武雄4322","lat":33.18472603,"lng":130.02278655,"geo_status":"db","era":"昭和18頃","year":1943,"year_source":"db","year_min":1943,"year_max":1943,"year_label":null,"structure":"木造平屋建，平屋建，建築面積274㎡","structure_material":"木造平屋建","registered":"1999.08.23(平成11.08.23)","register_no":"41 － 0013","desc":"塾舎及び寄宿舎棟の西側にあって、北面して建つ上質の建物。平面は、洋間及び広縁付きの大広間及び座敷等からなる棟を中心に、北側に玄関ホール・和室・厨房等を配した構成になる。設計は遠藤新と伝え、迎賓館としての品格を備えた建物である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001310"},{"id":"00007934","register_sub_id":"101","register_pk":"108914","name":"杉森家住宅主屋","kana":"すぎもりけじゅうたくしゅおく","category":"文化福祉","subcategory":"建築物","type_guess":"主屋・住宅","type_guess_confidence":"high","period":"明治","pref":"佐賀県","address":"佐賀県武雄市山内町大字宮野字水尾345","lat":33.20190944,"lng":129.92316585,"geo_status":"db","era":"明治24／昭和45改修","year":1891,"year_source":"db","year_min":1891,"year_max":1891,"year_label":null,"structure":"木造2階建、瓦葺、建築面積202㎡","structure_material":"木造2階建","registered":"2009.11.02(平成21.11.02)","register_no":"41-0076","desc":"敷地のほぼ中央に東面して建ち、南北２２ｍ東西１２ｍ、入母屋造及び切妻造、桟瓦葺である。正面左手に張り出す、もと待合室は、外壁を下見板張とし、アーチ状の破風板を付けたポーチを構える。明治期の診療所及び製薬所としての平面構成を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007934"},{"id":"00007935","register_sub_id":"101","register_pk":"108915","name":"杉森家住宅二階門","kana":"すぎもりけじゅうたくにかいもん","category":"文化福祉","subcategory":"建築物","type_guess":"主屋・住宅","type_guess_confidence":"high","period":"明治","pref":"佐賀県","address":"佐賀県武雄市山内町大字宮野字水尾345","lat":33.2017372,"lng":129.92332314,"geo_status":"db","era":"明治24／平成18改修","year":1891,"year_source":"db","year_min":1891,"year_max":1891,"year_label":null,"structure":"木造2階一部平屋建、瓦葺、建築面積38㎡","structure_material":"木造2階一部平屋建","registered":"2009.11.02(平成21.11.02)","register_no":"41-0077","desc":"主屋の前方、通りに面して建つ。桁行１５ｍ梁間３．２ｍ、切妻造桟瓦葺である。左右は長屋形式で、漆喰壁と腰竪板張とし、門の部分は櫓状に突き上げ、正・背面を下見板張とする。乗馬戴帽して潜ることを意図した設計と伝え、特徴的な表構えを形成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007935"},{"id":"00016613","register_sub_id":"101","register_pk":"574975","name":"清恵庵","kana":"せいけいあん","category":"文化福祉","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和後","pref":"佐賀県","address":"佐賀県佐賀市城内一丁目15-23","lat":33.24432278,"lng":130.30056889,"geo_status":"db","era":"昭和48年","year":1973,"year_source":"db","year_min":1973,"year_max":1973,"year_label":null,"structure":"木造平屋建、瓦葺及び銅板葺、建築面積72㎡","structure_material":"木造平屋建","registered":"2026.02.10(令和8.02.10)","register_no":"41 - 0136","desc":"佐賀城跡の外堀に南面して建つ茶室。設計は堀口捨己と早川正夫。入側を介して堀に面する開放的な七畳半広間と四畳半の茶室を南北に配し、東西に寄付、化粧室、台所を備える。寄付に舟入への階段を付す。照明を組み込んだ掛込天井など、堀口の特徴を示す茶室。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016613"},{"id":"00001209","register_sub_id":"101","register_pk":"102199","name":"多久市西渓公園寒鶯亭","kana":"たくしせいけいこうえんかんおうてい","category":"文化福祉","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"佐賀県","address":"佐賀県多久市多久町1975","lat":33.25762676,"lng":130.08900572,"geo_status":"db","era":"大正13","year":1924,"year_source":"db","year_min":1924,"year_max":1924,"year_label":null,"structure":"木造平屋建，瓦葺，建築面積293㎡","structure_material":"木造平屋建","registered":"1999.07.08(平成11.07.08)","register_no":"41 － 0011","desc":"地元出身の炭鉱主高取伊好が寄贈した公会堂建築。棟札から、設計は杵島炭鉱技師の大坪彌平、棟梁は舩津虎五郎であることが判明している。１６畳３室の四周に縁を回し、入母屋の大屋根を架け、北面の中央に車寄を設ける。木造和風公会堂建築の好例である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001209"},{"id":"00000368","register_sub_id":"101","register_pk":"101358","name":"徴古館","kana":"ちょうこかん","category":"文化福祉","subcategory":"建築物","type_guess":"会館","type_guess_confidence":"low","period":"昭和前","pref":"佐賀県","address":"佐賀県佐賀市松原2-59","lat":33.25154654,"lng":130.30134912,"geo_status":"db","era":"昭和2","year":1927,"year_source":"db","year_min":1927,"year_max":1927,"year_label":null,"structure":"鉄筋コンクリート造2階建，建築面積206㎡","structure_material":"鉄筋コンクリート造2階建","registered":"1997.11.05(平成9.11.05)","register_no":"41 － 0003","desc":"鍋島家所蔵資料を展示するための博物館施設として建てられた。正面ファサードは，ペアコラムを持つ半円形の車寄せと，２階の列柱からなり，背面は簡素な意匠である。県内のＲＣ造としては早い時期のものであり，また本格的な洋風意匠を持つ点にも特徴がある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000368"},{"id":"00015524","register_sub_id":"101","register_pk":"533539","name":"弓張岳展望所","kana":"ゆみはりだけてんぼうしょ","category":"文化福祉","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"昭和中","pref":"長崎県","address":"長崎県佐世保市矢岳町無番地","lat":33.17933056,"lng":129.70081667,"geo_status":"db","era":"昭和40年／平成22年改修","year":1965,"year_source":"db","year_min":1965,"year_max":1965,"year_label":null,"structure":"鉄筋コンクリート造、銅板葺、面積69㎡、基壇付","structure_material":"鉄筋コンクリート造","registered":"2025.08.06(令和7.08.06)","register_no":"42 - 0146","desc":"西海国立公園指定一〇周年を記念し、佐世保湾を望む丘に築いた展望所。前方二点と後方一点で支えた薄い反り屋根を鉄筋コンクリートＨＰシェル構造で実現。後方支柱は弓と波を象った本郷新のレリーフで飾る。自然景観にシャープな造形が際立つ坪井善勝の小品。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015524"},{"id":"00000493","register_sub_id":"101","register_pk":"101483","name":"芦北町立武徳殿","kana":"あしきたちょうりつぶとくでん","category":"文化福祉","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"熊本県","address":"熊本県葦北郡芦北町大字佐敷204","lat":32.30373348,"lng":130.50438978,"geo_status":"db","era":"昭和12","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"木造平屋建，スレート葺，建築面積336㎡","structure_material":"木造平屋建","registered":"1998.01.16(平成10.01.16)","register_no":"43 － 0008","desc":"剣道・柔道を行う武道場として建てられた（現在は歴史資料の保管場所に利用）。外観は２重だが，上は明かり取り窓で，内部は平屋である。１階窓を大きく開くなど武道場らしい工夫がみられる特徴ある建物で，町の象徴的な存在となっている。玄関は改造。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000493"},{"id":"00016462","register_sub_id":"101","register_pk":"536529","name":"菊池恵楓園旧事務本館","kana":"きくちけいふうえんきゅうじむほんかん","category":"文化福祉","subcategory":"建築物","type_guess":"会館","type_guess_confidence":"low","period":"昭和中","pref":"熊本県","address":"熊本県合志市栄3796","lat":32.88261111,"lng":130.75194167,"geo_status":"db","era":"昭和26年／令和4年改修","year":1951,"year_source":"db","year_min":1951,"year_max":1951,"year_label":null,"structure":"鉄筋コンクリート造2階建、建築面積849㎡、鐘塔付","structure_material":"鉄筋コンクリート造2階建","registered":"2025.11.17(令和7.11.17)","register_no":"43 - 0220","desc":"黒石原の高原地帯の一角に位置する、ハンセン病療養施設の旧事務本館。設計施工は竹中工務店。鉄筋コンクリート造二階建で、正面中央に車寄を設け、鐘楼を屹立させる。軒と連続する横長窓が水平性を強調し、希望の塔と呼ばれる鐘楼が印象的な外観を構成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016462"},{"id":"00005515","register_sub_id":"101","register_pk":"106503","name":"旧天草教育会館正門及び塀","kana":"きゅうあまくさきょういくかいかんせいもんおよびへい","category":"文化福祉","subcategory":"その他工作物","type_guess":"会館","type_guess_confidence":"high","period":"昭和前","pref":"熊本県","address":"熊本県天草市船之尾町336-3","lat":32.45731613,"lng":130.18658136,"geo_status":"db","era":"昭和9","year":1934,"year_source":"db","year_min":1934,"year_max":1934,"year_label":null,"structure":"正門 鉄筋コンクリート造、間口4.4m、左右袖塀付、塀 鉄筋コンクリート造、延長40m","structure_material":"正門 鉄筋コンクリート造","registered":"2006.03.27(平成18.03.27)","register_no":"43 － 0080","desc":"正門は高さ１．９ｍ，間口４．４ｍ，鉄筋コンクリート造モルタル仕上げの門柱２本から成り，左右に袖塀が付く。塀は敷地境に残る総延長４０ｍの鉄筋コンクリート造。正門，塀共に，本館の玄関ポーチ柱の台座と一体的な意匠となり，統一的な外観を形成。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005515"},{"id":"00005514","register_sub_id":"101","register_pk":"106502","name":"旧天草教育会館本館","kana":"きゅうあまくさきょういくかいかんほんかん","category":"文化福祉","subcategory":"建築物","type_guess":"会館","type_guess_confidence":"high","period":"昭和前","pref":"熊本県","address":"熊本県天草市船之尾町336-3","lat":32.45718379,"lng":130.18652314,"geo_status":"db","era":"昭和9","year":1934,"year_source":"db","year_min":1934,"year_max":1934,"year_label":null,"structure":"木造2階建、瓦葺、建築面積271㎡","structure_material":"木造2階建","registered":"2006.03.27(平成18.03.27)","register_no":"43 － 0079","desc":"敷地北西に北面して建つ。桁行１０間，梁間７間の規模で，切妻造，桟瓦葺の木造２階建。東側及び西側に階段室が付く。外壁は１階を下見板張，２階をモルタル塗とする。陸屋根庇を張出す玄関ポーチや欄間窓付引違窓からなる正面や東側外壁の丸窓等が特徴的。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005514"},{"id":"00006954","register_sub_id":"101","register_pk":"107936","name":"旧熊本回春病院日光回転家屋","kana":"きゅうくまもとかいしゅんびょういんにっこうかいてんかおく","category":"文化福祉","subcategory":"建築物","type_guess":"病院・診療","type_guess_confidence":"high","period":"昭和前","pref":"熊本県","address":"熊本県合志市栄3796","lat":32.88238908,"lng":130.7516971,"geo_status":"db","era":"昭和初期／昭和49移築","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"木造平屋建、板葺、建築面積4.2㎡","structure_material":"木造平屋建","registered":"2008.03.07(平成20.03.07)","register_no":"43 － 0103","desc":"ハンセン病救済施設内に日光浴を目的として建設された施設。床下５ヶ所に鋳鉄製キャスターを付け、建物全体が回転する。木造平屋建で、面積は４．２㎡。外壁は竪板張で、正面一杯に両開双折戸をたてる。機能に応じた、工夫がみられる建築である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006954"},{"id":"00014552","register_sub_id":"101","register_pk":"513966","name":"公衆温泉新温泉","kana":"こうしゅうおんせんしんおんせん","category":"文化福祉","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"熊本県","address":"熊本県人吉市紺屋町80-10","lat":32.21404167,"lng":130.75742778,"geo_status":"db","era":"昭和6年頃","year":1931,"year_source":"db","year_min":1931,"year_max":1931,"year_label":null,"structure":"木造平屋建、鉄板葺、建築面積192㎡","structure_material":"木造平屋建","registered":"2023.02.27(令和5.02.27)","register_no":"43 - 0200","desc":"温泉街に所在する公衆浴場。入母屋造妻入平屋建、正面庇付で男女別入口を開け、内部に番台を置き、脱衣室と浴場の田の字形平面としてガラス戸を多用。小屋はトラス組、ヴォールト形湯気抜を設ける。当地で大正から昭和にかけて建ち並んだ公衆温泉浴場の典型。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014552"},{"id":"00006036","register_sub_id":"101","register_pk":"107021","name":"慈愛園モード・パウラス記念資料館（旧宣教師館）","kana":"じあいえんもーど・ぱうらすきねんしりょうかん（きゅうせんきょうしかん）","category":"文化福祉","subcategory":"建築物","type_guess":"博物館","type_guess_confidence":"high","period":"昭和前","pref":"熊本県","address":"熊本県熊本市神水1-633-1","lat":32.784943,"lng":130.742249,"geo_status":"db","era":"昭和2","year":1927,"year_source":"db","year_min":1927,"year_max":1927,"year_label":null,"structure":"木造2階建、スレート葺、建築面積87㎡","structure_material":"木造2階建","registered":"2007.05.15(平成19.05.15)","register_no":"43 － 0086","desc":"広大な敷地の中央部に東西棟で南面して建つ。切妻造，スレート葺の木造２階建で，１階南側にリビングを置き，西に玄関，東にダイニングを配し，２階に寝室４室を設ける。西面に駒形の妻を２重に見せ，２階南面には大きく屋根窓を突き出す特徴的な形式をもつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006036"},{"id":"00009682","register_sub_id":"101","register_pk":"194678","name":"髙木医院","kana":"たかきいいん","category":"文化福祉","subcategory":"建築物","type_guess":"病院・診療","type_guess_confidence":"high","period":"昭和前","pref":"熊本県","address":"熊本県菊池市隈府字城山1323他","lat":32.98544362,"lng":130.81189827,"geo_status":"db","era":"昭和6","year":1931,"year_source":"db","year_min":1931,"year_max":1931,"year_label":null,"structure":"木造2階建、スレート葺、建築面積114㎡","structure_material":"木造2階建","registered":"2013.06.21(平成25.06.21)","register_no":"43 － 0122","desc":"県立菊池高校の向いに建つ木造二階建の医院建築で、一階を診療所、二階を応接間などとする。外観はハーフティンバー風とし、半切妻の銅板葺屋根にドーマー窓を載せ、玄関ポーチや窓廻りなどを中心に洋風意匠を巧みに取入れる。昭和初期の隈府の面影を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009682"},{"id":"00000374","register_sub_id":"101","register_pk":"101364","name":"水俣市立蘇峰記念館（旧淇水文庫）","kana":"みなまたしりつそほうきねんかん（きゅうきすいぶんこ）","category":"文化福祉","subcategory":"建築物","type_guess":"博物館","type_guess_confidence":"high","period":"昭和前","pref":"熊本県","address":"熊本県水俣市陣内1-101-1","lat":32.21144771,"lng":130.4083839,"geo_status":"db","era":"昭和4","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"鉄筋コンクリート造2階建，建築面積288㎡","structure_material":"鉄筋コンクリート造2階建","registered":"1997.11.05(平成9.11.05)","register_no":"43 － 0005","desc":"徳富蘇峰が自らの父の名前をとって建てた図書館。現在では記念館として用いられている。設計は地元の技術者渡辺録治によるが，蘇峰自身も関わったとされる。軒周りなどに装飾が配されているが，全体としては簡素な外観で，早い時期のＲＣ造建築の好例である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000374"},{"id":"00006975","register_sub_id":"101","register_pk":"107957","name":"リデル、ライト両女史記念館（旧熊本回春病院らい菌研究所）","kana":"りでる、らいとりょうじょしきねんかん（きゅうくまもとかいしゅんびょういんらいきんけんきゅうじょ）","category":"文化福祉","subcategory":"建築物","type_guess":"博物館","type_guess_confidence":"high","period":"大正","pref":"熊本県","address":"熊本県熊本市黒髪5-1","lat":32.81898291,"lng":130.73076593,"geo_status":"db","era":"大正8／昭和10増築","year":1919,"year_source":"db","year_min":1919,"year_max":1919,"year_label":null,"structure":"木造2階建、瓦葺、建築面積171㎡","structure_material":"木造2階建","registered":"2008.03.07(平成20.03.07)","register_no":"43 － 0102","desc":"東西に長い寄棟造桟瓦葺の建物で、北面西端を半間突き出すL字型平面とし、正面中央にポーチを設ける。基礎は煉瓦造で石貼とする。１階を下見板張、２階をモルタル仕上げとし、白色に塗装する。１階庇や出窓、２階正面の手摺、建具など、瀟洒な印象を与える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006975"},{"id":"00004480","register_sub_id":"101","register_pk":"105470","name":"龍驤館","kana":"りゅうじょうかん","category":"文化福祉","subcategory":"建築物","type_guess":"会館","type_guess_confidence":"low","period":"大正","pref":"熊本県","address":"熊本県宇城市三角町三角浦1320-22","lat":32.62212166,"lng":130.45608138,"geo_status":"db","era":"大正7","year":1918,"year_source":"db","year_min":1918,"year_max":1918,"year_label":null,"structure":"木造平屋一部2階建、瓦葺及び銅板葺、建築面積234㎡","structure_material":"木造平屋一部2階建","registered":"2004.11.08(平成16.11.08)","register_no":"43 － 0075","desc":"三角旧港東南に南面して建ち，桁行１５ｍ梁間９．２ｍの棟の南面両隅に，テラスで結ばれた宝形造，方形平面の二棟を配する。屋根は破風付の寄棟造で，軒下小壁ではハーフティンバー風に木部を見せる。大正期らしい簡略化されたスティックスタイルの建築物。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004480"},{"id":"00007324","register_sub_id":"101","register_pk":"108306","name":"臼杵市立臼杵図書館荘田平五郎記念子ども図書館","kana":"うすきしりつうすきとしょかんしょうだへいごろうきねんこどもとしょかん","category":"文化福祉","subcategory":"建築物","type_guess":"図書館","type_guess_confidence":"high","period":"大正","pref":"大分県","address":"大分県臼杵市大字臼杵字祇園洲5","lat":33.121655,"lng":131.798691,"geo_status":"db","era":"大正7／平成15改修","year":1918,"year_source":"db","year_min":1918,"year_max":1918,"year_label":null,"structure":"木造2階建、瓦葺、建築面積197㎡","structure_material":"木造2階建","registered":"2008.07.08(平成20.07.08)","register_no":"44 － 0139","desc":"道路北側に占める敷地の南寄りに位置する。桁行１７ｍ梁間１２ｍ規模の木造２階建で、東西棟の入母屋造桟瓦葺とし、１階に庇をまわす。外壁は全面に下見板張で、東面中央に出入口を設ける。妻は漆喰塗とし、獅子口には「圖」の文字をあしらう。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007324"},{"id":"00007325","register_sub_id":"101","register_pk":"108307","name":"臼杵市立臼杵図書館文庫","kana":"うすきしりつうすきとしょかんぶんこ","category":"文化福祉","subcategory":"建築物","type_guess":"博物館","type_guess_confidence":"high","period":"大正","pref":"大分県","address":"大分県臼杵市大字臼杵字祇園洲5","lat":33.121754,"lng":131.798767,"geo_status":"db","era":"大正7","year":1918,"year_source":"db","year_min":1918,"year_max":1918,"year_label":null,"structure":"土蔵造3階建、瓦葺、建築面積60㎡","structure_material":"土蔵造3階建","registered":"2008.07.08(平成20.07.08)","register_no":"44 － 0140","desc":"子ども図書館の北側に並行して建つ。土蔵造３階建、切妻造桟瓦葺で、各階上部に水切り瓦を付ける。漆喰仕上げで、北面は各階に８ヶ所の窓を穿ち、採光を取る。南面中央に出入口を開き、鉄扉をたてる。内部も漆喰仕上げで、窓位置に合わせて書棚を配する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007325"},{"id":"00014442","register_sub_id":"101","register_pk":"511431","name":"旧大分県立大分図書館（アートプラザ）","kana":"きゅうおおいたけんりつおおいたとしょかん（あーとぷらざ）","category":"文化福祉","subcategory":"建築物","type_guess":"図書館","type_guess_confidence":"high","period":"昭和後","pref":"大分県","address":"大分県大分市荷揚町3-31","lat":33.24054722,"lng":131.60949444,"geo_status":"db","era":"昭和41年／平成9年改修","year":1966,"year_source":"db","year_min":1966,"year_max":1966,"year_label":null,"structure":"鉄筋コンクリート造地上3階地下1階建、建築面積1，600㎡","structure_material":"鉄筋コンクリート造地上3階地下1階建","registered":"2022.10.31(令和4.10.31)","register_no":"44 - 0234","desc":"建築家磯崎新の初期代表作。鉄筋コンクリート造三階建、地下一階の図書館建築。二階にエントランスを配し、一階・地下に書庫、二・三階に閲覧室等を配す。打放しの中空梁、巨大なペアウォールを用い、スキップフロアを多用した巧みな空間構成は独創的である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014442"},{"id":"00000421","register_sub_id":"101","register_pk":"101411","name":"旧小幡記念図書館","kana":"きゅうおばたきねんとしょかん","category":"文化福祉","subcategory":"建築物","type_guess":"図書館","type_guess_confidence":"high","period":"昭和前","pref":"大分県","address":"大分県中津市1385","lat":33.60306499,"lng":131.1845894,"geo_status":"db","era":"昭和13","year":1938,"year_source":"db","year_min":1938,"year_max":1938,"year_label":null,"structure":"木造2階建，瓦葺，建築面積213㎡","structure_material":"木造2階建","registered":"1997.12.12(平成9.12.12)","register_no":"44 － 0018","desc":"慶應義塾の塾長をつとめた小幡篤次郎の寄贈図書を中心に明治４１年に設立された記念図書館を建て替えたもの。木造２階建で，立ちが高く，石張りの玄関ポーチ，連続するアーチ窓，軒廻りの装飾等に特徴がある。旧城下町に建つひときわ目立つ洋風建築である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000421"},{"id":"00002869","register_sub_id":"101","register_pk":"103859","name":"旧長田医院","kana":"きゅうながたいいん","category":"文化福祉","subcategory":"建築物","type_guess":"病院・診療","type_guess_confidence":"high","period":"昭和前","pref":"大分県","address":"大分県豊後大野市三重町市場1600-3","lat":32.98055471,"lng":131.58454709,"geo_status":"db","era":"昭和2","year":1927,"year_source":"db","year_min":1927,"year_max":1927,"year_label":null,"structure":"木造2階建、瓦葺、建築面積85㎡","structure_material":"木造2階建","registered":"2002.06.25(平成14.06.25)","register_no":"44 － 0082","desc":"木造２階建の病院建築。街路側は中央に玄関ポーチを備える洋風の立面を持ち，背面側はほぼ和風の意匠とする。１階には手術室・診察室，控室など病院機能を備え，２階には床棚を備える広間と四畳半の和室２室を配する。現在では喫茶店として活用されている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002869"},{"id":"00004193","register_sub_id":"101","register_pk":"105183","name":"竹瓦温泉","kana":"たけがわらおんせん","category":"文化福祉","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"大分県","address":"大分県別府市元町16-23","lat":33.277424,"lng":131.506012,"geo_status":"db","era":"昭和13","year":1938,"year_source":"db","year_min":1938,"year_max":1938,"year_label":null,"structure":"木造2階建、瓦葺、建築面積712㎡","structure_material":"木造2階建","registered":"2004.06.09(平成16.06.09)","register_no":"44 － 0101","desc":"中央は入母屋造の２階建で，１階が休憩所や脱衣所，２階が床・棚付の畳敷大広間になる。浴室は東側に突出する平屋建で，西側の寄棟造の平屋建は砂風呂になる。変化に富んだ外観や正面の唐破風玄関など，重厚かつ豪華なつくりで，温泉街の象徴的な存在である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004193"},{"id":"00000111","register_sub_id":"101","register_pk":"101101","name":"野口病院管理棟","kana":"のぐちびょういんかんりとう","category":"文化福祉","subcategory":"建築物","type_guess":"病院・診療","type_guess_confidence":"high","period":"大正","pref":"大分県","address":"大分県別府市野口中町６-33","lat":33.28143237,"lng":131.49811394,"geo_status":"db","era":"大正11","year":1922,"year_source":"db","year_min":1922,"year_max":1922,"year_label":null,"structure":"木造2階建、瓦葺、建築面積563㎡","structure_material":"木造2階建","registered":"1996.12.20(平成8.12.20)","register_no":"44 － 0002","desc":"東側に尖塔屋根を軸とする左右対称のファサードを持ち，背面に２列に棟が伸び，中庭を囲む構成をとる。グレーのモルタルススペイン壁の上部に白漆喰のハーフティンバーがのる外壁に特徴があり，まちなみ景観のシンボルとして親しまれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000111"},{"id":"00005687","register_sub_id":"101","register_pk":"106675","name":"浜田温泉資料館","kana":"はまだおんせんしりょうかん","category":"文化福祉","subcategory":"建築物","type_guess":"博物館","type_guess_confidence":"high","period":"昭和前","pref":"大分県","address":"大分県別府市亀川浜田町3-21","lat":33.32996258,"lng":131.4941245,"geo_status":"db","era":"昭和10","year":1935,"year_source":"db","year_min":1935,"year_max":1935,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積145㎡","structure_material":"木造平屋建","registered":"2006.08.03(平成18.08.03)","register_no":"44 － 0116","desc":"亀川海岸砂丘上の共同浴場として建設。東面して建つ桁行１４ｍ，梁間８ｍの木造平屋建で，入母屋造，銅板葺。望楼状の宝形屋根を載せ東面と西面に千鳥破風を飾り，正面玄関を唐破風とする。平成１７年の修復工事により片側の浴室上に床を張り展示室とした。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005687"},{"id":"00012079","register_sub_id":"101","register_pk":"211020","name":"石井記念友愛社静養館","kana":"いしいきねんゆうあいしゃせいようかん","category":"文化福祉","subcategory":"建築物","type_guess":"会館","type_guess_confidence":"low","period":"大正","pref":"宮崎県","address":"宮崎県児湯郡木城町大字椎木字上中原644-1","lat":32.142472,"lng":131.448512,"geo_status":"db","era":"大正13年","year":1924,"year_source":"db","year_min":1924,"year_max":1924,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積152㎡","structure_material":"木造平屋建","registered":"2017.10.27(平成29.10.27)","register_no":"45-91","desc":"岡山で孤児救済活動を行なっていた石井十次が、理想的農村共同体を築くために開墾した地に建つ。静養館は明治一二年に岡山に建てられた二階建西洋館を大正二年に移築し、同一三年に現在の姿に改造・移築されたもの。当地開墾の歴史を伝える建物である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012079"},{"id":"00012080","register_sub_id":"101","register_pk":"211021","name":"石井記念友愛社方舟館","kana":"いしいきねんゆうあいしゃはこぶねかん","category":"文化福祉","subcategory":"建築物","type_guess":"会館","type_guess_confidence":"low","period":"大正","pref":"宮崎県","address":"宮崎県児湯郡木城町大字椎木字上中原644-1","lat":32.142408,"lng":131.448186,"geo_status":"db","era":"大正14年","year":1925,"year_source":"db","year_min":1925,"year_max":1925,"year_label":null,"structure":"木造2階建、瓦葺、建築面積80㎡、鐘楼付","structure_material":"木造2階建","registered":"2017.10.27(平成29.10.27)","register_no":"45-92","desc":"当地での開墾事業に当たり職員の集会等に利用された建物。木造二階建、建築面積八〇平方メートルで、上部に鐘楼を設ける。内部は玄関奥左を事務室、右を書庫とし、書庫の奥に和室を設ける。二階は一室とする。特異な外観で、開墾地のシンボルとして知られている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012080"},{"id":"00005527","register_sub_id":"101","register_pk":"106515","name":"旧外山医院","kana":"きゅうとやまいいん","category":"文化福祉","subcategory":"建築物","type_guess":"病院・診療","type_guess_confidence":"high","period":"昭和前","pref":"宮崎県","address":"宮崎県日南市油津1-9-1","lat":31.5835045,"lng":131.402679,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"木造2階建、瓦葺、建築面積73㎡","structure_material":"木造2階建","registered":"2006.03.27(平成18.03.27)","register_no":"45 － 0036","desc":"北西の角地に建ち，桁行５間半，梁間４間の規模で，木造２階建，寄棟造，桟瓦葺とし，外壁をモルタル塗とし，現在は外側に鉄板を張る。１，２階に縦長窓を並べ，北側に玄関をとり，１階を全て洋室とし，２階に和室４室をとる。市内に数少ない洋館の意匠をもつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005527"},{"id":"00012855","register_sub_id":"101","register_pk":"367758","name":"服部植物研究所","kana":"はっとりしょくぶつけんきゅうしょ","category":"文化福祉","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和中","pref":"宮崎県","address":"宮崎県日南市飫肥六丁目3888","lat":31.62894278,"lng":131.35507583,"geo_status":"db","era":"昭和20年代／昭和50年代移築","year":1945,"year_source":"db","year_min":1945,"year_max":1945,"year_label":null,"structure":"木造2階一部平屋建、瓦葺、建築面積108㎡","structure_material":"木造2階一部平屋建","registered":"2019.03.29(平成31.03.29)","register_no":"45 － 105","desc":"飫肥旧城下の本町通りに北面して建つ。東の東西棟平屋建の洋館と西の南北棟二階建の和館からなる。寄棟造桟瓦葺、外壁はドイツ壁。洋館は板敷で格天井の一空間とし、和館二階に畳敷の個室を配する。町並みの整備が進んだ本町通りのランドマークとなっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012855"},{"id":"00014443","register_sub_id":"101","register_pk":"511432","name":"服部植物研究所研究・標本棟","kana":"はっとりしょくぶつけんきゅうしょけんきゅうひょうほんとう","category":"文化福祉","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和中","pref":"宮崎県","address":"宮崎県日南市飫肥六丁目3888","lat":31.62491389,"lng":131.35509444,"geo_status":"db","era":"昭和29年頃／同42年改修","year":1954,"year_source":"db","year_min":1954,"year_max":1954,"year_label":null,"structure":"木造2階建、瓦葺、建築面積52㎡","structure_material":"木造2階建","registered":"2022.10.31(令和4.10.31)","register_no":"45 - 0113","desc":"飫肥城下の本町通りに面する敷地奥に北面して建つ。木造総二階建で、１・２階を貫く柱形に戸袋を収め、垂直性を強調した簡素な外観。標本を保管する２階は北面以外の開口部を狭め、日差しを抑える。世界的に著名なコケ専門研究所の創設時から残る研究施設。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014443"},{"id":"00013773","register_sub_id":"101","register_pk":"504981","name":"遠藤家住宅主屋","kana":"えんどうけじゅうたくおもや","category":"文化福祉","subcategory":"建築物","type_guess":"主屋・住宅","type_guess_confidence":"high","period":"江戸","pref":"鹿児島県","address":"鹿児島県西之表市西町7105","lat":30.73356278,"lng":130.99585972,"geo_status":"db","era":"天保11年(1840)／大正後期増築","year":1840,"year_source":"db","year_min":1840,"year_max":1840,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積242㎡","structure_material":"木造平屋建","registered":"2021.02.26(令和3.02.26)","register_no":"46 － 123","desc":"西之表市の中心部に建つ。近世の建築とみられる土間及び床上部二列四室の正面に続き間座敷、西に医院部分を増築した。主体部は切妻造桟瓦葺。増築部は赤土の壁に縁側の天井を曲面とするなど数寄屋風の造作をみせる。伝統家屋に近代和風の要素を加味した住宅。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013773"},{"id":"00007150","register_sub_id":"101","register_pk":"108132","name":"大崎公民館（旧大崎報公義會舘）本館","kana":"おおさきこうみんかん（きゅうおおさきほうこうぎかいかん）ほんかん","category":"文化福祉","subcategory":"建築物","type_guess":"会館","type_guess_confidence":"high","period":"明治","pref":"鹿児島県","address":"鹿児島県南さつま市加世田唐仁原6078-2他","lat":31.42587762,"lng":130.29258878,"geo_status":"db","era":"明治末期／大正末期増築","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治末期","structure":"石造及び鉄筋コンクリート造平屋一部2階建、瓦葺、建築面積309㎡","structure_material":"石造及び鉄筋コンクリート造平屋一部2階建","registered":"2008.04.18(平成20.04.18)","register_no":"46 － 0067","desc":"明治末期の平屋建石造会堂の前面に鉄筋コンクリート造２階建を増築し、桁行２８ｍ梁間１０ｍ規模とする。会堂演台まわりはイオニア式の柱や偏平アーチで飾られ、増築部は柱形頂部や玄関ポーチの縁取、正面の飾りなど独特で特異な意匠が随所に見られる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007150"},{"id":"00007151","register_sub_id":"101","register_pk":"108133","name":"大崎公民館（旧大崎報公義會舘）門及び石塀","kana":"おおさきこうみんかん（きゅうおおさきほうこうぎかいかん）もんおよびいしべい","category":"文化福祉","subcategory":"その他工作物","type_guess":"会館","type_guess_confidence":"high","period":"明治","pref":"鹿児島県","address":"鹿児島県南さつま市加世田唐仁原6078-2他","lat":31.42597588,"lng":130.2925969,"geo_status":"db","era":"明治末期・大正末期／昭和63移築","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治末期","structure":"門 コンクリート造門柱2基、間口3.5m 塀 石造、延長66m","structure_material":"門 コンクリート造門柱2基","registered":"2008.04.18(平成20.04.18)","register_no":"46 － 0068","desc":"石塀は、石造会堂と同時期築造の石積３段の敷地外周塀で、北辺はほぼ全長の４６ｍ、南辺は道路寄り２０ｍを残す。門は、増築部と同時期築造のコンクリート造門柱で、高さ２．１ｍ規模とし、正・側面に幾何学的なイオニア式風柱頭飾りを付けるのが特徴。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007151"},{"id":"00007148","register_sub_id":"101","register_pk":"108130","name":"鹿児島県立博物館（旧鹿児島県立図書館）","kana":"かごしまけんりつはくぶつかん（きゅうかごしまけんりつとしょかん）","category":"文化福祉","subcategory":"建築物","type_guess":"博物館","type_guess_confidence":"high","period":"昭和前","pref":"鹿児島県","address":"鹿児島県鹿児島市城山町1-1","lat":31.59399075,"lng":130.55269759,"geo_status":"db","era":"昭和2","year":1927,"year_source":"db","year_min":1927,"year_max":1927,"year_label":null,"structure":"鉄筋コンクリート造3階建、建築面積671㎡、塔屋付","structure_material":"鉄筋コンクリート造3階建","registered":"2008.04.18(平成20.04.18)","register_no":"46 － 0065","desc":"照国神社前交差点の角地に建つ。鉄筋コンクリート造３階建塔屋付で、鹿児島県建築課の設計による。担当は地元出身の岩下松雄。丸くした隅部に正面玄関を配し、階段室や塔屋に曲面を用いてダイナミックな構成とするなどに岩下松雄の作風がよく示されている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007148"},{"id":"00001024","register_sub_id":"101","register_pk":"102014","name":"鹿児島県立博物館考古資料館","kana":"かごしまけんりつはくぶつかんこうこしりょうかん","category":"文化福祉","subcategory":"建築物","type_guess":"博物館","type_guess_confidence":"high","period":"明治","pref":"鹿児島県","address":"鹿児島県鹿児島市城山町1-1","lat":31.59444945,"lng":130.55207783,"geo_status":"db","era":"明治16","year":1883,"year_source":"db","year_min":1883,"year_max":1883,"year_label":null,"structure":"石造２階建，建築面積337㎡","structure_material":"石造２階建","registered":"1998.12.11(平成10.12.11)","register_no":"46 － 0001","desc":"興業館として建設され，鹿児島県の産業振興に大きな役割を果たした。石造アーチ橋の文化圏にある鹿児島ならではの石造建築で，洋風を基調としながら，随所に和風モチーフの細部を混在させた特異な建造物として知られる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001024"},{"id":"00005070","register_sub_id":"101","register_pk":"106060","name":"鹿児島市中央公民館","kana":"かごしましちゅうおうこうみんかん","category":"文化福祉","subcategory":"建築物","type_guess":"会館","type_guess_confidence":"high","period":"昭和前","pref":"鹿児島県","address":"鹿児島県鹿児島市山下町","lat":31.595329,"lng":130.554459,"geo_status":"db","era":"昭和2","year":1927,"year_source":"db","year_min":1927,"year_max":1927,"year_label":null,"structure":"鉄筋コンクリート造地上3階地下1階建、建築面積1126㎡","structure_material":"鉄筋コンクリート造地上3階地下1階建","registered":"2005.11.10(平成17.11.10)","register_no":"46 － 0020","desc":"建物周囲にドライエリアを設け，ラーメン構造のＲＣ造，地下１階地上３階建とする。正面立面及び平面をほぼ左右対称とし，玄関両脇に階段室塔屋を配し，その間に４本のピラスター，イスラム風尖頭アーチの窓を設置するなど，中央重視の特徴ある意匠とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005070"},{"id":"00002871","register_sub_id":"101","register_pk":"103861","name":"加治木町立図書館（旧郷土館陳列館）","kana":"かじきちょうりつとしょかん（きゅうきょうどかんちんれつかん）","category":"文化福祉","subcategory":"建築物","type_guess":"図書館","type_guess_confidence":"high","period":"昭和前","pref":"鹿児島県","address":"鹿児島県姶良市加治木町仮屋町250","lat":31.74116408,"lng":130.66403922,"geo_status":"db","era":"昭和12","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積228㎡","structure_material":"木造平屋建","registered":"2002.06.25(平成14.06.25)","register_no":"46 － 0012","desc":"木造平屋建。旧町役場が移転した跡地に郷土館として建設された。当初はコの字型平面で，正面には２重に破風を連ねた玄関を突出させ，全体を洋風の意匠でまとめている。内部は１室とし現在では図書館として活用されている。洋風展示館建築の好例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002871"},{"id":"00002872","register_sub_id":"101","register_pk":"103862","name":"加治木町立図書館（旧郷土館日本館）","kana":"かじきちょうりつとしょかん（きゅうきょうどかんにほんかん）","category":"文化福祉","subcategory":"建築物","type_guess":"図書館","type_guess_confidence":"high","period":"昭和前","pref":"鹿児島県","address":"鹿児島県姶良市加治木町仮屋町250","lat":31.741009,"lng":130.663956,"geo_status":"db","era":"昭和12","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積90㎡","structure_material":"木造平屋建","registered":"2002.06.25(平成14.06.25)","register_no":"46 － 0013","desc":"旧郷土館陳列館の南西側に接して建つ。内部は１２畳，６畳，６畳の３室を南北に並べ，東西南の三方に縁を廻らす。東面には玄関を設け，屋根も三方に庇を設けている。内部・外部ともに全体を和風の意匠でまとめており，洋風の陳列館と好対照をなす。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002872"},{"id":"00002873","register_sub_id":"101","register_pk":"103863","name":"加治木町立図書館（旧郷土館付属石造倉庫）","kana":"かじきちょうりつとしょかん（きゅうきょうどかんふぞくせきぞうそうこ）","category":"文化福祉","subcategory":"建築物","type_guess":"図書館","type_guess_confidence":"high","period":"昭和前","pref":"鹿児島県","address":"鹿児島県姶良市加治木町仮屋町250","lat":31.74122294,"lng":130.66417235,"geo_status":"db","era":"昭和12","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"石造2階建、瓦葺、建築面積26㎡","structure_material":"石造2階建","registered":"2002.06.25(平成14.06.25)","register_no":"46 － 0014","desc":"旧郷土館陳列館の北東に建つ桁行５．９ｍ，梁間４．０ｍの小規模な石造倉庫。加治木石と呼ばれる地元産の凝灰岩を用い，屋根は切妻造，桟瓦葺で，南面に庇をかけて出入口を置く。腰部２段分は石材表面を平滑に仕上げ，金属製の換気口を設けている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002873"},{"id":"00007819","register_sub_id":"101","register_pk":"108800","name":"旧鯵坂医院","kana":"きゅうあじさかいいん","category":"文化福祉","subcategory":"建築物","type_guess":"病院・診療","type_guess_confidence":"high","period":"昭和前","pref":"鹿児島県","address":"鹿児島県南さつま市加世田武田18278","lat":31.4130529,"lng":130.31817822,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造平屋建、瓦葺、建築面積160㎡","structure_material":"木造平屋建","registered":"2009.08.07(平成21.08.07)","register_no":"46-0082","desc":"旧道西側の敷地中央に位置する。木造平屋建桟瓦葺、建築面積１６０㎡。東西棟の切妻造の主棟に、東・西に落棟、北に寄棟造、南に下屋を付け、変化に富む屋根を構成する。外壁は下見板張で、軒には軒持送りを付ける。用水路や石垣が残る地域にたつ洋風医院建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007819"},{"id":"00006471","register_sub_id":"101","register_pk":"107454","name":"旧黒木回春堂医院","kana":"きゅうくろきかいしゅんどういいん","category":"文化福祉","subcategory":"建築物","type_guess":"病院・診療","type_guess_confidence":"high","period":"昭和前","pref":"鹿児島県","address":"鹿児島県日置市吹上町永吉14307","lat":31.56110869,"lng":130.35245594,"geo_status":"db","era":"昭和3","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積52㎡","structure_material":"木造平屋建","registered":"2007.10.02(平成19.10.02)","register_no":"46 － 0047","desc":"通り沿いに建つ木造平屋建。建築面積５２㎡、桟瓦葺で、両妻を半切妻とする。外壁は、内法間を下見板張として周囲に縦長の上げ下げ窓を配し、その上下は竪板張とする。玄関の欄間や軒下の持送りを洋風意匠で瀟洒に飾る、白色の外観が印象的な医院建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006471"},{"id":"00013775","register_sub_id":"101","register_pk":"505343","name":"當山紀念館","kana":"とうやまきねんかん","category":"文化福祉","subcategory":"建築物","type_guess":"会館","type_guess_confidence":"low","period":"昭和前","pref":"沖縄県","address":"沖縄県国頭郡金武町字金武4","lat":26.4564,"lng":127.92624167,"geo_status":"db","era":"昭和10年","year":1935,"year_source":"db","year_min":1935,"year_max":1935,"year_label":null,"structure":"鉄筋コンクリート造平屋建、陸屋根、建築面積96㎡","structure_material":"鉄筋コンクリート造平屋建","registered":"2021.02.26(令和3.02.26)","register_no":"47 － 88","desc":"金武町の中心部に位置。鉄筋コンクリート造平屋建で屋根は陸屋根。南北一五メートル、東西六・四メートルで南端に玄関ポーチを付け、矩形の窓を並べる。内部は一室である。玄関ポーチのアーチや北端の八角形の窓以外は装飾要素を持たない平明な意匠の記念館。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013775"},{"id":"00006672","register_sub_id":"101","register_pk":"107655","name":"弐六荘","kana":"にろくそう","category":"文化福祉","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"沖縄県","address":"沖縄県島尻郡北大東村字港33","lat":25.95439912,"lng":131.28691763,"geo_status":"db","era":"昭和15","year":1940,"year_source":"db","year_min":1940,"year_max":1940,"year_label":null,"structure":"木造平屋建、鉄板葺、建築面積243㎡","structure_material":"木造平屋建","registered":"2007.12.05(平成19.12.05)","register_no":"47 － 0060","desc":"燐鉱採掘事業において宿泊や娯楽等に使われた。北面して建ち、東に切妻造妻入、西に入母屋造妻入を並行に設け、その間を繋ぐ工字型平面を基本に、突出が多く複雑な屋根構成になる。正面はガラス戸をたて開放的であり、屋根勾配が緩く、穏やかな佇まいをみせる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006672"},{"id":"00010087","register_sub_id":"101","register_pk":"196234","name":"美里村屋","kana":"んざとぅむらやー","category":"文化福祉","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和中","pref":"沖縄県","address":"沖縄県沖縄市美里3-22-1","lat":26.34621113,"lng":127.81433557,"geo_status":"db","era":"昭和29／昭和49改修","year":1954,"year_source":"db","year_min":1954,"year_max":1954,"year_label":null,"structure":"木造平屋建、瓦葺、164㎡","structure_material":"木造平屋建","registered":"2014.04.25(平成26.04.25)","register_no":"47 － 0082","desc":"通り沿いの敷地に南面して建ち、木造平屋建、入母屋造瓦葺である。内部は広い一室の集会所周囲に廊下を廻らし、西面にトコを構える。西端に土間、東端に台所を附属する。開放的な平面で、前面の軒を雨端柱で支えるなど地方的特色を備えた、もと公民館建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010087"},{"id":"00013015","register_sub_id":"101","register_pk":"368328","name":"大野家住宅主屋（旧大野組事務所兼主屋）","kana":"おおのけじゅうたくしゅおく（きゅうおおのぐみじむしょけんしゅおく）","category":"産業2次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"北海道","address":"北海道士別市大通西一丁目1918-5他","lat":44.17975833,"lng":142.39013333,"geo_status":"db","era":"昭和2年／昭和13年頃増築","year":1927,"year_source":"db","year_min":1927,"year_max":1927,"year_label":null,"structure":"木造平屋建、金属板葺、建築面積138㎡","structure_material":"木造平屋建","registered":"2019.12.05(令和1.12.05)","register_no":"01 － 0158","desc":"市中心部にある旧家の住宅。主屋は敷地西辺中央に西面して建つ木造平屋建で、正面中央に入母屋造の玄関を付す。内部は前後二列に三室ずつ並べ、北側に床を備えた座敷などを、南側に応接室などの洋室を配す。和風民家への洋室導入の有り様を伝える上質な建物。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013015"},{"id":"00012673","register_sub_id":"101","register_pk":"367577","name":"旧肥田製陶工場（ＥＢＲＩ）","kana":"きゅうひだせいとうこうじょう（えぶり）","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"昭和中","pref":"北海道","address":"北海道江別市東野幌町3-3他","lat":43.09551083,"lng":141.53537694,"geo_status":"db","era":"昭和26年頃／平成27年改修、昭和28年頃増築","year":1951,"year_source":"db","year_min":1951,"year_max":1951,"year_label":null,"structure":"煉瓦造及び鉄筋コンクリート造平屋建、金属板葺、建築面積1300㎡","structure_material":"煉瓦造及び鉄筋コンクリート造平屋建","registered":"2019.03.29(平成31.03.29)","register_no":"01 － 153","desc":"窯業で栄えた市中心部にある旧窯業工場。切妻造鉄板葺の平屋建、Ｔ字型平面の煉瓦造にＬ字型平面の鉄筋コンクリート造の増築部を連ねた不整形な建物で、増築部の壁を煉瓦積として一体感のある外観をつくる。近代江別の象徴的存在で、地域に親しまれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012673"},{"id":"00005703","register_sub_id":"101","register_pk":"106691","name":"旧北炭夕張炭鉱専用鉄道高松跨線橋","kana":"きゅうほくたんゆうばりたんこうせんようてつどうたかまつこせんきょう","category":"産業2次","subcategory":"土木構造物","type_guess":"橋","type_guess_confidence":"high","period":"昭和前","pref":"北海道","address":"北海道夕張市高松","lat":43.06576431,"lng":141.98820904,"geo_status":"db","era":"昭和11","year":1936,"year_source":"db","year_min":1936,"year_max":1936,"year_label":null,"structure":"鉄筋コンクリート造単アーチ橋、橋長22m、幅員2.4m","structure_material":"鉄筋コンクリート造単アーチ橋","registered":"2006.10.18(平成18.10.18)","register_no":"01 － 0070","desc":"夕張鉄道に接続する旧炭鉱専用鉄道に架かる跨線橋で，中心市街地の東方に位置する。橋長２２ｍ，幅員２．４ｍ規模の開腹式鉄筋コンクリート造単アーチ橋で，地盤高の異なる地点を結ぶために橋桁を傾斜させ，特徴ある外観を呈する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005703"},{"id":"00005708","register_sub_id":"101","register_pk":"106696","name":"旧北炭夕張炭鉱高松ズリ捨線拱橋","kana":"きゅうほくたんゆうばりたんこうたかまつずりすてせんこうきょう","category":"産業2次","subcategory":"土木構造物","type_guess":"橋","type_guess_confidence":"high","period":"昭和中","pref":"北海道","address":"北海道夕張市高松","lat":43.063839,"lng":141.991425,"geo_status":"db","era":"昭和26","year":1951,"year_source":"db","year_min":1951,"year_max":1951,"year_label":null,"structure":"鉄筋コンクリート造7連アーチ橋、橋長59m、幅員8.6m","structure_material":"鉄筋コンクリート造7連アーチ橋","registered":"2006.10.18(平成18.10.18)","register_no":"01 － 0074","desc":"天龍坑坑口より約４３０ｍ南東に位置する。橋長５９ｍ，幅員８．６ｍ規模の鉄筋コンクリート造７連アーチ橋。各アーチは半円形で，スパン６．０ｍとする。坑内や選鉱場等で生じるズリを夕張市内最大のズリ山に搬出するために築かれた高松ズリ捨線の設備。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005708"},{"id":"00005709","register_sub_id":"101","register_pk":"106697","name":"旧北炭夕張炭鉱高松ズリ捨線スキップ隧道","kana":"きゅうほくたんゆうばりたんこうたかまつずりすてせんすきっぷずいどう","category":"産業2次","subcategory":"土木構造物","type_guess":"隧道・坑口","type_guess_confidence":"high","period":"昭和中","pref":"北海道","address":"北海道夕張市高松","lat":43.06359893,"lng":141.99933021,"geo_status":"db","era":"昭和26","year":1951,"year_source":"db","year_min":1951,"year_max":1951,"year_label":null,"structure":"コンクリート造、延長73m","structure_material":"コンクリート造","registered":"2006.10.18(平成18.10.18)","register_no":"01 － 0075","desc":"高松ズリ捨線拱橋の約１４０ｍ東方に位置する。延長７３ｍ，幅５．５ｍ規模の直線状のコンクリート造隧道で，両端にはコンクリート造の坑門を構える。建設当初，スキップと呼ばれる特殊な鉄製炭車が走行したことから，今もスキップ隧道の名で親しまれる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005709"},{"id":"00005716","register_sub_id":"101","register_pk":"106704","name":"旧北炭夕張炭鉱高松ズリ捨線ベルト隧道西坑門","kana":"きゅうほくたんゆうばりたんこうたかまつずりすてせんべるとずいどうにしこうもん","category":"産業2次","subcategory":"土木構造物","type_guess":"隧道・坑口","type_guess_confidence":"high","period":"昭和中","pref":"北海道","address":"北海道夕張市社光","lat":43.0653725,"lng":141.98647481,"geo_status":"db","era":"昭和26","year":1951,"year_source":"db","year_min":1951,"year_max":1951,"year_label":null,"structure":"コンクリート造、幅8.9m","structure_material":"コンクリート造","registered":"2006.10.18(平成18.10.18)","register_no":"01 － 0076","desc":"高松ズリ捨線拱橋の約５００ｍ西方に位置する。直径２．５ｍの半円アーチ断面形状を有する隧道の西端のコンクリート造坑門で，幅８．９ｍ，高さ３．３ｍとする。内部にベルトコンベヤーが設けられていたことからベルト隧道の名で親しまれる施設の一部。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005716"},{"id":"00005705","register_sub_id":"101","register_pk":"106693","name":"旧北炭夕張炭鉱天龍坑資材斜坑坑口","kana":"きゅうほくたんゆうばりたんこうてんりゅうこうしざいしゃこうこうぐち","category":"産業2次","subcategory":"その他工作物","type_guess":"隧道・坑口","type_guess_confidence":"high","period":"明治","pref":"北海道","address":"北海道夕張市高松","lat":43.06638466,"lng":141.98793634,"geo_status":"db","era":"明治33","year":1900,"year_source":"db","year_min":1900,"year_max":1900,"year_label":null,"structure":"煉瓦造、幅7.2m","structure_material":"煉瓦造","registered":"2006.10.18(平成18.10.18)","register_no":"01 － 0072","desc":"人車斜坑坑口の東方に位置する。煉瓦５枚厚，スパン４ｍの半円アーチを築き，壁面にはピラスター，コーニス等や，「天龍坑」と陰刻された扁額を付ける。人車斜坑坑口と共に，北炭夕張鉱業所管内で最大級の採炭量を誇った第二鉱区における代表的遺構のひとつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005705"},{"id":"00005704","register_sub_id":"101","register_pk":"106692","name":"旧北炭夕張炭鉱天龍坑人車斜坑坑口","kana":"きゅうほくたんゆうばりたんこうてんりゅうこうじんしゃしゃこうこうぐち","category":"産業2次","subcategory":"その他工作物","type_guess":"隧道・坑口","type_guess_confidence":"high","period":"明治","pref":"北海道","address":"北海道夕張市高松","lat":43.06630393,"lng":141.98786842,"geo_status":"db","era":"明治33","year":1900,"year_source":"db","year_min":1900,"year_max":1900,"year_label":null,"structure":"煉瓦造、幅11m","structure_material":"煉瓦造","registered":"2006.10.18(平成18.10.18)","register_no":"01 － 0071","desc":"高松跨線橋の約６５ｍ北方に位置する。当初，第三斜坑と呼ばれた煉瓦造斜坑の坑口の一つ。錐形に盛り上げた石材を要石に用いた煉瓦４枚厚，スパン２．５ｍの半円アーチを築き，ピラスター，コーニス等を付けた壁面の左右に翼部を張り出す堂々とした構え。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005704"},{"id":"00005707","register_sub_id":"101","register_pk":"106695","name":"旧北炭夕張炭鉱模擬坑道","kana":"きゅうほくたんゆうばりたんこうもぎこうどう","category":"産業2次","subcategory":"土木構造物","type_guess":"隧道・坑口","type_guess_confidence":"high","period":"明治","pref":"北海道","address":"北海道夕張市高松","lat":43.06641985,"lng":141.98854859,"geo_status":"db","era":"明治後期／昭和初期増築","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"煉瓦造及びコンクリート造、延長180m、補強鉄骨付","structure_material":"煉瓦造及びコンクリート造","registered":"2006.10.18(平成18.10.18)","register_no":"01 － 0073","desc":"資材斜坑坑口の約４０ｍ東方に位置する。天龍坑の補助的な坑道を一部利用して，見学用及び鉱員養成用に整備した施設。斜坑と水平坑道を組み合わせた，延長１８０ｍの煉瓦造アーチ坑道を，古レールを用いて一部補強したもので，今も公開施設として利用される。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005707"},{"id":"00005720","register_sub_id":"101","register_pk":"106708","name":"小林酒造一番蔵","kana":"こばやししゅぞういちばんぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"北海道","address":"北海道夕張郡栗山町錦3-109","lat":43.0615049,"lng":141.76960571,"geo_status":"db","era":"明治33／大正7増築","year":1900,"year_source":"db","year_min":1900,"year_max":1900,"year_label":null,"structure":"煉瓦造平屋建、鉄板葺、建築面積473㎡","structure_material":"煉瓦造平屋建","registered":"2006.10.18(平成18.10.18)","register_no":"01 － 0081","desc":"敷地中央に東西棟で建つ。桁行２６間，梁間６間の規模で，煉瓦造平屋建，切妻造，鉄板葺とする。東西に各１箇所，北側に４箇所の出入口を設ける。小屋はキングポストトラスとする。酒造所最大の蔵で，軒蛇腹にデンティルを設けるが，意匠は全体に質素である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005720"},{"id":"00005719","register_sub_id":"101","register_pk":"106707","name":"小林酒造旧資材庫（昔の酒道具展示館）","kana":"こばやししゅぞうきゅうしざいこ（むかしのさけどうぐてんじかん）","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"大正","pref":"北海道","address":"北海道夕張郡栗山町錦3-109","lat":43.06140972,"lng":141.7703545,"geo_status":"db","era":"大正9","year":1920,"year_source":"db","year_min":1920,"year_max":1920,"year_label":null,"structure":"煉瓦造2階建、瓦葺、建築面積114㎡","structure_material":"煉瓦造2階建","registered":"2006.10.18(平成18.10.18)","register_no":"01 － 0080","desc":"敷地南東隅に位置し，桁行１３ｍ，梁間８．５ｍの規模で，煉瓦造２階建，切妻造，桟瓦葺とし，北東に出入口を設ける。１階内部は棟通りに２本の丸柱を立て，東端に階段室を設ける。２階は１室とする。１階には妻側に２箇所，平側に３箇所の控壁を付ける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005719"},{"id":"00005715","register_sub_id":"101","register_pk":"106703","name":"小林酒造旧事務所（蔵元北の錦記念館）","kana":"こばやししゅぞうきゅうじむしょ（くらもときたのにしききねんかん）","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"昭和前","pref":"北海道","address":"北海道夕張郡栗山町錦3-109","lat":43.06165394,"lng":141.7706215,"geo_status":"db","era":"昭和19","year":1944,"year_source":"db","year_min":1944,"year_max":1944,"year_label":null,"structure":"鉄筋コンクリート造2階建、瓦葺、建築面積200㎡","structure_material":"鉄筋コンクリート造2階建","registered":"2006.10.18(平成18.10.18)","register_no":"01 － 0077","desc":"敷地東隅に位置し，桁行１５ｍ，梁間１０ｍの規模で，ＲＣ造２階建，寄棟造，桟瓦葺とする。南東を正面とし，石張の玄関を構える。１階は丸柱２本を棟通りに立て，間仕切の無い広い空間とする。背面と側面に階段室を突出させ，外壁をタイル貼とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005715"}];
